    vscode.commands.registerCommand('claudeHub.refreshAgents', () => {
      agentsProvider.refresh();
    })
  );

  context.subscriptions.push(
    vscode.commands.registerCommand('claudeHub.refreshOrchestrations', () => {
      orchestrationsProvider.refresh();
    })
  );

  context.subscriptions.push(
    vscode.commands.registerCommand('claudeHub.refreshHistory', () => {
      historyProvider.refresh();
    })
  );

  context.subscriptions.push(
    vscode.commands.registerCommand('claudeHub.runAgent', async (item?: AgentTreeItem) => {
      let agent = item?.agent;

      if (!agent) {
        // Quick pick if not called from tree
        try {
          const agents = await fetchAgents();
          const picked = await vscode.window.showQuickPick(
            agents.map((a) => ({
              label: a.name,
              description: a.model || '',
              detail: a.description || '',
              agent: a,
            })),
            { placeHolder: 'Select an agent to run' }
          );
          if (!picked) return;
          agent = picked.agent;
        } catch {
          void vscode.window.showErrorMessage('Cannot connect to Claude Hub. Is it running?');
          return;
        }
      }

      if (!agent || !agent.filename) return;

      AgentPanel.show(agent, context.extensionUri);
    })
  );

  context.subscriptions.push(
    vscode.commands.registerCommand('claudeHub.runOrchestration', async (item?: OrchestrationTreeItem) => {
      let orchestration = item?.orchestration;

      if (!orchestration) {
        const { fetchOrchestrations } = await import('./api');
        try {
          const orcs = await fetchOrchestrations();
          if (orcs.length === 0) {
            void vscode.window.showInformationMessage('No orchestrations saved. Create one in Claude Hub first.');
            return;
          }
          const picked = await vscode.window.showQuickPick(
            orcs.map((o) => ({
              label: o.name,
              description: `${o.nodes.length} nodes`,
              detail: `ID: ${o.id}`,
              orchestration: o,
            })),
            { placeHolder: 'Select a pipeline to run' }
          );
          if (!picked) return;
          orchestration = picked.orchestration;
        } catch {
          void vscode.window.showErrorMessage('Cannot connect to Claude Hub. Is it running?');
          return;
        }
      }

      if (!orchestration || !orchestration.id) return;

      OrchestrationPanel.show(orchestration, context.extensionUri);
    })
  );

  context.subscriptions.push(
    vscode.commands.registerCommand('claudeHub.viewRunDetail', async (item?: HistoryTreeItem) => {
      if (!item?.run?.id) return;

      try {
        const detail = await fetchRunDetail(item.run.id);
        const doc = await vscode.workspace.openTextDocument({
          content: formatRunDetail(detail),
          language: 'markdown',
        });
        await vscode.window.showTextDocument(doc, { preview: true });
      } catch {
        void vscode.window.showErrorMessage('Failed to load run details');
      }
    })
  );

  context.subscriptions.push(
    vscode.commands.registerCommand('claudeHub.openHub', () => {
      const url = vscode.workspace.getConfiguration('claudeHub').get<string>('serverUrl') || 'http://localhost:3847';
      void vscode.env.openExternal(vscode.Uri.parse(url));
    })
  );

  context.subscriptions.push(
    vscode.commands.registerCommand('claudeHub.checkStatus', async () => {
      const online = await checkHealth();
      if (online) {
        statusBarItem.text = '$(check) Claude Hub';
        statusBarItem.tooltip = 'Claude Hub is running';
        statusBarItem.color = undefined;
        void vscode.window.showInformationMessage('Claude Hub is online and connected.');
      } else {
        statusBarItem.text = '$(error) Claude Hub';
        statusBarItem.tooltip = 'Claude Hub is not reachable';
        statusBarItem.color = new vscode.ThemeColor('errorForeground');
        void vscode.window.showWarningMessage('Claude Hub is not reachable. Check if the server is running.');
      }
    })
  );

  // ── Auto-connect on startup ──
  const autoConnect = vscode.workspace.getConfiguration('claudeHub').get<boolean>('autoConnect');
  if (autoConnect) {
    const online = await checkHealth();
    if (online) {
      statusBarItem.text = '$(check) Claude Hub';
      statusBarItem.tooltip = 'Claude Hub is running';
    } else {
      statusBarItem.text = '$(warning) Claude Hub';
      statusBarItem.tooltip = 'Claude Hub is not reachable — click to retry';
      statusBarItem.color = new vscode.ThemeColor('problemsWarningIcon.foreground');
    }
    statusBarItem.show();
  }
}

function formatRunDetail(detail: RunDetail): string {
  const d = detail;

  let md = `# Run: ${d.orchestrationName ?? 'Unknown'}\n\n`;
  md += `**Task:** ${d.task ?? ''}\n\n`;
  md += `**Status:** ${d.status ?? ''}\n`;
  md += `**Started:** ${d.startedAt ?? ''}\n`;
  md += `**Duration:** ${d.duration ? Math.round(d.duration / 1000) + 's' : '?'}\n`;
  md += `**Nodes:** ${d.nodeCount ?? 0}\n\n`;
  md += `---\n\n`;

  if (d.logs && Array.isArray(d.logs)) {
    md += `## Run Log\n\n`;
    for (const log of d.logs) {
      md += `### ${log.label ?? 'Node'} (${log.type ?? ''})\n\n`;
      if (log.output) md += `\`\`\`\n${log.output}\n\`\`\`\n\n`;
      if (log.error) md += `**Error:** ${log.error}\n\n`;
    }
  }

  if (d.outputs && typeof d.outputs === 'object') {
    md += `## Node Outputs\n\n`;
    for (const [nodeId, output] of Object.entries(d.outputs)) {
      md += `### ${nodeId}\n\n\`\`\`\n${output}\n\`\`\`\n\n`;
    }
  }

  return md;
}

export function deactivate(): void {
  statusBarItem?.dispose();
}

