// --- Run History ---
const MAX_RUN_HISTORY = 50;

function loadRunHistory() {
  try {
    if (fs.existsSync(RUN_HISTORY_PATH)) return JSON.parse(fs.readFileSync(RUN_HISTORY_PATH, 'utf-8'));
  } catch {}
  return [];
}

function saveRunHistory(list) {
  // Keep only the most recent runs
  fs.writeFileSync(RUN_HISTORY_PATH, JSON.stringify(list.slice(0, MAX_RUN_HISTORY), null, 2));
}

app.get('/api/orchestrations/runs', (req, res) => {
