    if (fs.existsSync(rankora)) {
      fs.copyFileSync(rankora, destScript);
    } else {
      // Inline canonical script
      const scriptContent = `#!/usr/bin/env node
/**
 * Auto-Screenshot Utility — installed by Claude Hub
 * Usage:
 *   node scripts/screenshot.mjs                  # Desktop, all routes
 *   node scripts/screenshot.mjs --viewport all   # Mobile + tablet + desktop
 *   node scripts/screenshot.mjs --dark           # Dark mode
 *   node scripts/screenshot.mjs --full-page      # Full scroll capture
 *   node scripts/screenshot.mjs --routes /,/dashboard
 */
import { chromium } from 'playwright';
import { mkdirSync, existsSync, readFileSync, writeFileSync, readdirSync } from 'fs';
import { join, resolve } from 'path';

const SCREENSHOT_DIR = resolve('.screenshots');
const VIEWPORTS = {
  mobile:  { width: 375, height: 812 },
  tablet:  { width: 768, height: 1024 },
  desktop: { width: 1440, height: 900 },
};

function detectPort() {
  const files = [
    { path: 'vite.config.ts', regex: /port:\\s*(\\d+)/ },
    { path: 'vite.config.js', regex: /port:\\s*(\\d+)/ },
    { path: 'next.config.js', regex: /port:\\s*(\\d+)/ },
    { path: 'next.config.mjs', regex: /port:\\s*(\\d+)/ },
  ];
  for (const f of files) {
    if (existsSync(f.path)) {
      const m = readFileSync(f.path, 'utf-8').match(f.regex);
      if (m) return parseInt(m[1]);
    }
  }
  if (existsSync('vite.config.ts') || existsSync('vite.config.js')) return 8080;
  return 3000;
}

function detectRoutes() {
  const routes = new Set(['/']);
  const routeFiles = ['src/App.tsx', 'src/app/App.tsx'];
  for (const file of routeFiles) {
    if (!existsSync(file)) continue;
    const content = readFileSync(file, 'utf-8');
    for (const m of content.matchAll(/path=["']([^"']+)["']/g)) {
      const r = m[1];
      if (!r.includes(':') && !r.includes('*') && !r.includes('$')) {
        routes.add(r.startsWith('/') ? r : '/' + r);
      }
    }
  }
  if (existsSync('src/pages')) {
    try {
      for (const f of readdirSync('src/pages').filter(f => f.endsWith('.tsx') && f !== 'NotFound.tsx')) {
        const name = f.replace('.tsx', '');
        routes.add(name === 'Index' ? '/' : '/' + name.charAt(0).toLowerCase() + name.slice(1));
      }
    } catch {}
  }
  return [...routes].sort();
}

function parseArgs() {
  const args = process.argv.slice(2);
  const p = {};
  for (let i = 0; i < args.length; i++) {
    if (args[i] === '--port') p.port = parseInt(args[++i]);
    if (args[i] === '--routes') p.routes = args[++i].split(',');
    if (args[i] === '--viewport') p.viewport = args[++i];
    if (args[i] === '--dark') p.dark = true;
    if (args[i] === '--full-page') p.fullPage = true;
  }
  return p;
}

async function run() {
  const args = parseArgs();
  const port = args.port || detectPort();
  const baseUrl = \`http://localhost:\${port}\`;
  const routes = args.routes || detectRoutes();
  const viewportKeys = args.viewport === 'all' ? Object.keys(VIEWPORTS) : [args.viewport || 'desktop'];

  try {
    await fetch(baseUrl, { signal: AbortSignal.timeout(3000) });
  } catch {
    console.error(\`Dev server not running at \${baseUrl}. Start it: npm run dev\`);
    process.exit(1);
  }

  mkdirSync(SCREENSHOT_DIR, { recursive: true });
  const browser = await chromium.launch({ headless: true });
  const results = [];

  for (const vpKey of viewportKeys) {
    const context = await browser.newContext({
      viewport: VIEWPORTS[vpKey],
      deviceScaleFactor: 2,
      colorScheme: args.dark ? 'dark' : 'light',
    });
    const page = await context.newPage();
    const consoleErrors = [];
    page.on('console', msg => { if (msg.type() === 'error') consoleErrors.push(msg.text()); });

    for (const route of routes) {
      const filename = \`\${vpKey}_\${route.replace(/\\//g, '_').replace(/^_/, '') || 'home'}\${args.dark ? '_dark' : ''}.png\`;
      try {
        const response = await page.goto(\`\${baseUrl}\${route}\`, { waitUntil: 'networkidle', timeout: 15000 });
        await page.waitForTimeout(2000);
        await page.screenshot({ path: join(SCREENSHOT_DIR, filename), fullPage: args.fullPage || false });
        results.push({ route, viewport: vpKey, file: filename, status: response?.status(), consoleErrors: [...consoleErrors] });
        console.log(\`  OK  \${vpKey.padEnd(7)} \${route.padEnd(20)} -> \${filename}\`);
        consoleErrors.length = 0;
      } catch (err) {
        results.push({ route, viewport: vpKey, file: null, status: 'FAILED', error: err.message });
        console.log(\`  ERR \${vpKey.padEnd(7)} \${route.padEnd(20)} -> \${err.message}\`);
      }
    }
    await context.close();
  }

  await browser.close();
  const summary = { total: results.length, success: results.filter(r => r.file).length, failed: results.filter(r => !r.file).length };
  writeFileSync(join(SCREENSHOT_DIR, 'manifest.json'), JSON.stringify({ timestamp: new Date().toISOString(), baseUrl, routes, viewports: viewportKeys, screenshots: results, summary }, null, 2));
  console.log(\`\\n  \${summary.success} captured, \${summary.failed} failed\\n\`);
}

run().catch(err => { console.error(err.message); process.exit(1); });
`;
      fs.writeFileSync(destScript, scriptContent, 'utf-8');
    }

