// Rename / move file
app.post('/api/memory/move', (req, res) => {
  const { from, to } = req.body;
  const absFrom = resolveMemoryPath(from);
  const absTo = resolveMemoryPath(to);
  if (!absFrom || !absTo) return res.status(400).json({ error: 'Invalid path' });
