 */
async function listTemplates() {
  try {
    const res = await fetch(`${CLAUDE_HUB_URL}/api/templates`)
    if (!res.ok) throw new Error(`HTTP ${res.status}`)
    return await res.json()
  } catch {
    return []
  }
}

module.exports = { callAgent, listAgents, isOnline, listCategories, listTemplates }

