            <Clock className="w-10 h-10 mx-auto mb-3 opacity-30" />
            <p className="text-sm">No schedules yet</p>
            <p className="text-xs mt-1">Create a schedule to run agents automatically on a cron timer</p>
          </div>
        )}
      </div>
    </div>
  )
}

