import { useState, useEffect } from 'react'
import { Activity, CheckCircle, XCircle, Filter } from 'lucide-react'
import { getAnalyticsRuns } from '../lib/api'
import type { AgentRunEntry } from '../lib/api'

const SOURCE_COLORS: Record<string, string> = {
  playground: 'bg-purple-500/20 text-purple-400',
  orchestration: 'bg-blue-500/20 text-blue-400',
  schedule: 'bg-green-500/20 text-green-400',
  webhook: 'bg-orange-500/20 text-orange-400',
  sdk: 'bg-gray-500/20 text-gray-400',
  'ai-chat': 'bg-pink-500/20 text-pink-400',
}

const SOURCES = ['all', 'playground', 'orchestration', 'schedule', 'webhook', 'sdk', 'ai-chat']

function timeAgo(ts: string): string {
  const diff = Date.now() - new Date(ts).getTime()
  if (diff < 60000) return 'just now'
  if (diff < 3600000) return `${Math.floor(diff / 60000)}m ago`
  if (diff < 86400000) return `${Math.floor(diff / 3600000)}h ago`
  return new Date(ts).toLocaleDateString('en-US', { month: 'short', day: 'numeric', hour: '2-digit', minute: '2-digit' })
}

function formatDuration(ms: number): string {
  if (ms < 1000) return `${ms}ms`
  return `${(ms / 1000).toFixed(1)}s`
}

export default function RunHistoryPage() {
  const [runs, setRuns] = useState<AgentRunEntry[]>([])
  const [total, setTotal] = useState(0)
  const [loading, setLoading] = useState(true)
  const [sourceFilter, setSourceFilter] = useState('all')
  const [statusFilter, setStatusFilter] = useState('all')
  const [offset, setOffset] = useState(0)
  const limit = 50

  const load = () => {
    setLoading(true)
    const params: Record<string, string | number> = { limit, offset }
    if (sourceFilter !== 'all') params.source = sourceFilter
    if (statusFilter !== 'all') params.status = statusFilter
    getAnalyticsRuns(params as Record<string, string>)
      .then(data => { setRuns(data.runs); setTotal(data.total) })
      .catch(() => {})
      .finally(() => setLoading(false))
  }

  useEffect(() => { setOffset(0) }, [sourceFilter, statusFilter])
  useEffect(() => { load() }, [sourceFilter, statusFilter, offset])

  return (
    <div className="max-w-6xl mx-auto p-8 space-y-6">
      <div>
        <h1 className="text-2xl font-bold flex items-center gap-2">
          <Activity className="w-6 h-6" /> Run History
        </h1>
        <p className="text-text-muted text-sm mt-1">All agent runs from every source — unified view</p>
      </div>

      {/* Filters */}
      <div className="flex items-center gap-4 flex-wrap">
        <div className="flex items-center gap-2">
          <Filter className="w-3.5 h-3.5 text-text-muted" />
          <span className="text-xs text-text-muted">Source:</span>
          <div className="flex gap-1">
            {SOURCES.map(s => (
              <button
                key={s}
                onClick={() => setSourceFilter(s)}
                className={`px-2.5 py-1 text-[11px] rounded-lg font-medium transition-colors ${
                  sourceFilter === s
                    ? 'bg-accent text-white'
                    : 'bg-surface-2 text-text-muted hover:text-text'
                }`}
              >
                {s}
              </button>
            ))}
          </div>
        </div>
        <div className="flex items-center gap-2">
          <span className="text-xs text-text-muted">Status:</span>
          {['all', 'success', 'error'].map(s => (
            <button
              key={s}
              onClick={() => setStatusFilter(s)}
              className={`px-2.5 py-1 text-[11px] rounded-lg font-medium transition-colors ${
                statusFilter === s
                  ? 'bg-accent text-white'
                  : 'bg-surface-2 text-text-muted hover:text-text'
              }`}
            >
              {s}
            </button>
          ))}
        </div>
        <span className="text-xs text-text-muted ml-auto">{total} total runs</span>
      </div>

      {/* Table */}
      <div className="bg-surface rounded-xl border border-border overflow-hidden">
        {loading ? (
          <div className="p-8 text-center text-text-muted text-sm">Loading...</div>
        ) : runs.length === 0 ? (
