        )}
      </div>

      <Handle type="source" position={Position.Right} className="!w-3.5 !h-3.5 !bg-accent !border-2 !border-surface !-right-[7px]" />
    </div>
  )
}

const nodeTypes: NodeTypes = { agentNode: AgentNode }

// ---- Orchestration Templates ----
