      { id: 'n2', type: 'agentNode', position: { x: 320, y: 150 }, data: { label: 'Nova', isCustom: true, description: 'Market research & competitive intel', instructions: 'You are a market research specialist. Research the top 3-5 competitors for the given product/feature. Analyze their strengths, weaknesses, pricing, and user complaints. Identify a USP opportunity.' } },
      { id: 'n3', type: 'agentNode', position: { x: 580, y: 150 }, data: { label: 'Arya', isCustom: true, description: 'Architecture & technical planning', instructions: 'You are a system architect. Based on the competitive research, design a technical architecture including: stack selection, data model, API design, auth strategy, and sprint plan. Output a concrete, buildable plan.' } },
      { id: 'n4', type: 'agentNode', position: { x: 840, y: 150 }, data: { label: 'Koda', isCustom: true, description: 'Build the feature', instructions: 'You are a senior full-stack developer. Based on the architecture plan, write production-grade code. Include all files needed with proper TypeScript types, error handling, and best practices.' } },
    ],
    edges: [
      { id: 'e1', source: 'n1', target: 'n2', animated: true },
