                        >
                          <StopCircle className="w-4 h-4" /> Stop
                        </button>
                      )}
                    </>
                  )}
                </div>
              </div>

              {/* Progress bar */}
              {(running || runLog.length > 0) && (
                <div className="px-5 py-2.5 border-b border-border shrink-0">
