                          className="px-2.5 py-1.5 text-text-muted hover:text-red hover:bg-red-muted rounded-lg transition-colors"
                        >
                          <Trash className="w-3.5 h-3.5" />
                        </button>
                      </div>
                    </div>
                  ))
                )}
              </div>
            )}
          </div>
