// ── Project Conversations — per-project chat with agents ─────────────────────
const CONVERSATIONS_DIR = path.join(__dirname, '..', 'conversations');
if (!fs.existsSync(CONVERSATIONS_DIR)) fs.mkdirSync(CONVERSATIONS_DIR, { recursive: true });

function getProjectConversationsPath(projectId) {
  return path.join(CONVERSATIONS_DIR, `${projectId}.json`);
}
function loadProjectConversations(projectId) {
  const fp = getProjectConversationsPath(projectId);
  try { if (fs.existsSync(fp)) return JSON.parse(fs.readFileSync(fp, 'utf-8')); } catch {}
  return [];
}
function saveProjectConversations(projectId, list) {
  fs.writeFileSync(getProjectConversationsPath(projectId), JSON.stringify(list, null, 2));
}

// List conversations for a project
app.get('/api/projects/:projectId/conversations', rateLimit('read'), (req, res) => {
  const convos = loadProjectConversations(req.params.projectId);
  res.json(convos.map(c => ({
    id: c.id,
    title: c.title,
    agentName: c.agentName,
    messageCount: c.messages.length,
    lastMessageAt: c.messages.length > 0 ? c.messages[c.messages.length - 1].timestamp : c.createdAt,
    createdAt: c.createdAt,
  })));
});

// Get a single conversation
app.get('/api/projects/:projectId/conversations/:id', rateLimit('read'), (req, res) => {
  const convos = loadProjectConversations(req.params.projectId);
  const convo = convos.find(c => c.id === req.params.id);
  if (!convo) return res.status(404).json({ error: 'Conversation not found' });
  res.json(convo);
});

// Create a new conversation
app.post('/api/projects/:projectId/conversations', rateLimit('write'), (req, res) => {
  const { title, agentName } = req.body;
  if (!title) return res.status(400).json({ error: 'title required' });
  const convo = {
    id: genId(),
    projectId: req.params.projectId,
    title,
    agentName: agentName || null,
    messages: [],
    createdAt: new Date().toISOString(),
    updatedAt: new Date().toISOString(),
  };
  const convos = loadProjectConversations(req.params.projectId);
  convos.unshift(convo);
  saveProjectConversations(req.params.projectId, convos);
  res.json(convo);
});

// Delete a conversation
app.delete('/api/projects/:projectId/conversations/:id', rateLimit('write'), (req, res) => {
  const convos = loadProjectConversations(req.params.projectId);
  saveProjectConversations(req.params.projectId, convos.filter(c => c.id !== req.params.id));
  res.json({ ok: true });
});

// Send a message in a conversation (streaming SSE)
app.post('/api/projects/:projectId/conversations/:id/send', rateLimit('heavy'), (req, res) => {
  const { message } = req.body;
  if (!message) return res.status(400).json({ error: 'message required' });

  const projectId = req.params.projectId;
  const convos = loadProjectConversations(projectId);
  const convoIdx = convos.findIndex(c => c.id === req.params.id);
  if (convoIdx < 0) return res.status(404).json({ error: 'Conversation not found' });

  const convo = convos[convoIdx];

  // Add user message
  convo.messages.push({ role: 'user', content: message, timestamp: new Date().toISOString() });
  convo.updatedAt = new Date().toISOString();
  saveProjectConversations(projectId, convos);

  // Build prompt with agent instructions + conversation history + project context
  let instructions = '';
  if (convo.agentName) {
    const agentPath = path.join(CLAUDE_DIR, 'agents', convo.agentName + '.md');
    if (fs.existsSync(agentPath)) {
      instructions = fs.readFileSync(agentPath, 'utf-8');
    }
  }

  // Load project CLAUDE.md for context
  let projectContext = '';
  try {
    const config = loadConfig();
    const projects = discoverProjects(config.projectDirs);
    const project = projects.find(p => p.id === projectId);
    if (project) {
      const claudeMdPath = path.join(project.path, 'CLAUDE.md');
      if (fs.existsSync(claudeMdPath)) {
        projectContext = `\n\n## Project Context (${project.name} CLAUDE.md):\n${fs.readFileSync(claudeMdPath, 'utf-8').slice(0, 3000)}`;
      }
    }
  } catch {}

  let prompt = '';
  if (instructions) prompt += instructions + '\n\n---\n\n';
  prompt += `You are having a conversation about the project "${projectId}".${projectContext}\n\n`;
  prompt += '## Conversation History:\n';
  for (const msg of convo.messages) {
    if (msg.role === 'user') prompt += `Human: ${msg.content}\n\n`;
    else if (msg.role === 'assistant') prompt += `Assistant: ${msg.content}\n\n`;
  }
  prompt += 'Assistant:';

  // Stream response
  res.setTimeout(0);
  res.setHeader('Content-Type', 'text/event-stream');
  res.setHeader('Cache-Control', 'no-cache');
  res.setHeader('Connection', 'keep-alive');
  res.flushHeaders();

  const claudePath = process.env.CLAUDE_PATH || 'claude';
  const childEnv = { ...process.env, HOME: os.homedir() };
  delete childEnv.CLAUDECODE;
  delete childEnv.CLAUDE_CODE_ENTRYPOINT;
  delete childEnv.CLAUDE_AGENT_SDK_VERSION;

  const proc = spawn(claudePath, ['-p'], { env: childEnv });
  let fullOutput = '';
  let responded = false;
  const startTime = Date.now();

  const endStream = (eventData) => {
    if (responded) return;
    responded = true;
    res.write(`data: ${JSON.stringify(eventData)}\n\n`);
    res.end();
  };

  proc.stdout.on('data', (data) => {
    const chunk = data.toString();
    fullOutput += chunk;
    res.write(`data: ${JSON.stringify({ type: 'chunk', content: chunk })}\n\n`);
  });

  proc.stderr.on('data', () => {});

  proc.on('close', (code) => {
    const trimmed = fullOutput.trim();
    if (code !== 0 && !trimmed) {
      endStream({ type: 'error', error: 'Agent failed to respond' });
    } else {
      // Save assistant message
      const freshConvos = loadProjectConversations(projectId);
      const freshIdx = freshConvos.findIndex(c => c.id === req.params.id);
      if (freshIdx >= 0) {
        freshConvos[freshIdx].messages.push({ role: 'assistant', content: trimmed, timestamp: new Date().toISOString() });
        freshConvos[freshIdx].updatedAt = new Date().toISOString();
        saveProjectConversations(projectId, freshConvos);
      }

      // Log to run tracker
      logAgentRun({
        agentName: convo.agentName || 'chat',
        prompt: message,
        output: trimmed,
        source: 'project-chat',
        duration: Date.now() - startTime,
        status: 'success',
        metadata: { projectId, conversationId: convo.id },
      });

      endStream({ type: 'done', content: trimmed });
    }
  });

  proc.on('error', (err) => {
    endStream({ type: 'error', error: err.message });
  });

  proc.stdin.write(prompt, 'utf8');
  proc.stdin.end();

  req.socket?.on('close', () => {
    if (!responded) { try { proc.kill(); } catch {} }
  });
});

// Project activity feed — runs filtered by project
app.get('/api/projects/:projectId/activity', rateLimit('read'), (req, res) => {
  const projectId = req.params.projectId;
  const runs = loadAgentRuns();
  const projectRuns = runs.filter(r =>
    r.metadata?.projectId === projectId ||
    r.metadata?.orchestrationId?.includes?.(projectId) ||
    r.source === 'project-chat' && r.metadata?.projectId === projectId
  );
  const limit = Math.min(parseInt(req.query.limit) || 50, 200);
  res.json({ total: projectRuns.length, runs: projectRuns.slice(0, limit) });
});

