              className="w-full px-2.5 py-1.5 text-xs bg-surface-2 border border-border rounded-lg focus:border-accent outline-none"
              autoFocus
              onKeyDown={e => { if (e.key === 'Enter') handleCreate() }}
            />
            <select
              value={newAgent}
