  useEffect(() => { setSelectedIdx(0) }, [query])

  const handleKeyDown = (e: React.KeyboardEvent) => {
    if (e.key === 'ArrowDown') { e.preventDefault(); setSelectedIdx(i => Math.min(i + 1, filtered.length - 1)) }
    if (e.key === 'ArrowUp') { e.preventDefault(); setSelectedIdx(i => Math.max(i - 1, 0)) }
    if (e.key === 'Enter' && filtered[selectedIdx]) { filtered[selectedIdx].action() }
  }

  if (!open) return null

  return (
    <div className="fixed inset-0 z-[100] flex items-start justify-center pt-[20vh]" onClick={() => setOpen(false)}>
      {/* Backdrop */}
      <div className="absolute inset-0 bg-black/60 backdrop-blur-sm" />

      {/* Palette */}
      <div
        className="relative w-full max-w-xl bg-surface border border-border rounded-2xl shadow-2xl overflow-hidden"
        onClick={e => e.stopPropagation()}
      >
        {/* Search */}
        <div className="flex items-center gap-3 px-5 py-4 border-b border-border">
          <Search className="w-5 h-5 text-text-muted shrink-0" />
          <input
            ref={inputRef}
            value={query}
            onChange={e => setQuery(e.target.value)}
            onKeyDown={handleKeyDown}
            placeholder="Search pages, agents, actions..."
            className="flex-1 bg-transparent text-sm text-text outline-none placeholder:text-text-muted"
          />
          <kbd className="text-[10px] text-text-muted bg-surface-2 px-1.5 py-0.5 rounded border border-border font-mono">ESC</kbd>
        </div>

        {/* Results */}
        <div className="max-h-[360px] overflow-y-auto py-2">
          {filtered.length === 0 ? (
            <div className="px-5 py-8 text-center text-text-muted text-sm">
              No results for "{query}"
            </div>
          ) : (
            <>
              {filtered.map((item, i) => {
                const Icon = item.icon
                return (
                  <button
                    key={item.id}
                    onClick={() => item.action()}
                    onMouseEnter={() => setSelectedIdx(i)}
                    className={`w-full flex items-center gap-3 px-5 py-2.5 text-left transition-colors ${
                      i === selectedIdx ? 'bg-accent/10 text-accent' : 'text-text hover:bg-surface-2'
                    }`}
                  >
                    <Icon className="w-4 h-4 shrink-0 opacity-60" />
                    <div className="flex-1 min-w-0">
                      <span className="text-sm font-medium truncate block">{item.label}</span>
                    </div>
                    <span className="text-[10px] text-text-muted bg-surface-2 px-1.5 py-0.5 rounded shrink-0">
                      {item.category}
                    </span>
                  </button>
                )
              })}
            </>
          )}
        </div>

        {/* Footer */}
        <div className="px-5 py-2.5 border-t border-border flex items-center gap-4 text-[10px] text-text-muted">
          <span><kbd className="bg-surface-2 px-1 rounded">↑↓</kbd> navigate</span>
          <span><kbd className="bg-surface-2 px-1 rounded">↵</kbd> select</span>
          <span><kbd className="bg-surface-2 px-1 rounded">esc</kbd> close</span>
        </div>
      </div>
    </div>
  )
}

import { useState, useEffect, useRef, useMemo, useCallback } from 'react'
import { useNavigate } from 'react-router-dom'
import {
  Search, Bot, Sparkles, BarChart3, Clock, Globe, Users, Target,
  FileText, Terminal, ShieldCheck, Brain, FlaskConical, LayoutTemplate,
  Settings, Wrench, BookOpen, Network, Activity, MessageSquare,
  LayoutDashboard,
} from 'lucide-react'
import { getUnifiedAgents, getSchedules, getWebhooks } from '../lib/api'

interface CommandItem {
  id: string
  label: string
  category: string
  icon: React.ElementType
  action: () => void
  keywords?: string
}

export default function CommandPalette() {
  const [open, setOpen] = useState(false)
  const [query, setQuery] = useState('')
  const [selectedIdx, setSelectedIdx] = useState(0)
  const [dynamicItems, setDynamicItems] = useState<CommandItem[]>([])
  const inputRef = useRef<HTMLInputElement>(null)
  const navigate = useNavigate()

  const go = useCallback((path: string) => { navigate(path); setOpen(false) }, [navigate])

  // Static navigation items
  const staticItems: CommandItem[] = useMemo(() => [
    { id: 'dashboard', label: 'Dashboard', category: 'Pages', icon: LayoutDashboard, action: () => go('/') },
    { id: 'agents', label: 'All Agents', category: 'Pages', icon: Bot, action: () => go('/agents'), keywords: 'agent list manage' },
    { id: 'commands', label: 'All Commands', category: 'Pages', icon: Terminal, action: () => go('/commands') },
    { id: 'rules', label: 'All Rules', category: 'Pages', icon: ShieldCheck, action: () => go('/rules') },
    { id: 'orchestration', label: 'Orchestration', category: 'Pages', icon: Sparkles, action: () => go('/orchestration'), keywords: 'pipeline dag workflow' },
    { id: 'playground', label: 'Playground', category: 'Pages', icon: FlaskConical, action: () => go('/playground'), keywords: 'test run agent' },
    { id: 'templates', label: 'Templates', category: 'Pages', icon: LayoutTemplate, action: () => go('/templates') },
    { id: 'org-chart', label: 'Org Chart', category: 'Pages', icon: Users, action: () => go('/org-chart'), keywords: 'hierarchy pipeline agents' },
    { id: 'goals', label: 'Goal Cascade', category: 'Pages', icon: Target, action: () => go('/goals'), keywords: 'mission project goals' },
    { id: 'analytics', label: 'Analytics', category: 'Pages', icon: BarChart3, action: () => go('/analytics'), keywords: 'cost tokens usage stats' },
    { id: 'runs', label: 'Run History', category: 'Pages', icon: Activity, action: () => go('/runs'), keywords: 'history logs' },
    { id: 'schedules', label: 'Schedules', category: 'Pages', icon: Clock, action: () => go('/schedules'), keywords: 'cron timer automatic' },
    { id: 'webhooks', label: 'Webhooks', category: 'Pages', icon: Globe, action: () => go('/webhooks'), keywords: 'trigger external event' },
    { id: 'claude-md', label: 'Global CLAUDE.md', category: 'Config', icon: FileText, action: () => go('/global/claude-md') },
    { id: 'memory', label: 'Memory Brain', category: 'Config', icon: Brain, action: () => go('/memory'), keywords: 'knowledge notes' },
    { id: 'memory-history', label: 'Memory History', category: 'Config', icon: Activity, action: () => go('/memory/history') },
    { id: 'how-it-works', label: 'How It Works', category: 'System', icon: Network, action: () => go('/how-it-works') },
    { id: 'setup', label: 'Setup & Status', category: 'System', icon: Wrench, action: () => go('/setup') },
    { id: 'docs', label: 'Documentation', category: 'System', icon: BookOpen, action: () => go('/docs') },
    { id: 'settings', label: 'Settings', category: 'System', icon: Settings, action: () => go('/settings'), keywords: 'config preferences slack' },
  ], [go])

  // Load dynamic items (agents, schedules, webhooks)
  useEffect(() => {
    if (!open) return
    Promise.all([
      getUnifiedAgents().catch(() => []),
      getSchedules().catch(() => []),
      getWebhooks().catch(() => []),
    ]).then(([agents, schedules, webhooks]) => {
      const items: CommandItem[] = []
      for (const a of agents) {
        items.push({
          id: `agent-${a.filename}`,
          label: a.name,
          category: 'Agents',
          icon: Bot,
          action: () => go(a.scope === 'global' ? `/global/agents/${a.filename}` : `/projects/${a.projectId}/agents/${a.filename}`),
          keywords: `${a.description} ${a.model} ${a.filename}`,
        })
      }
      for (const s of schedules) {
        items.push({
          id: `schedule-${s.id}`,
          label: `Schedule: ${s.name}`,
          category: 'Schedules',
          icon: Clock,
          action: () => go('/schedules'),
          keywords: `${s.agentName} ${s.cron}`,
        })
      }
      for (const w of webhooks) {
        items.push({
          id: `webhook-${w.id}`,
          label: `Webhook: ${w.name}`,
          category: 'Webhooks',
          icon: Globe,
          action: () => go('/webhooks'),
          keywords: `${w.agentName}`,
        })
      }
      setDynamicItems(items)
    })
  }, [open, go])

  const allItems = useMemo(() => [...staticItems, ...dynamicItems], [staticItems, dynamicItems])

  const filtered = useMemo(() => {
    if (!query) return allItems.slice(0, 20)
    const q = query.toLowerCase()
    return allItems
      .filter(item =>
        item.label.toLowerCase().includes(q) ||
        item.category.toLowerCase().includes(q) ||
        (item.keywords || '').toLowerCase().includes(q)
      )
      .slice(0, 15)
  }, [query, allItems])

  // Keyboard shortcut
  useEffect(() => {
    const handler = (e: KeyboardEvent) => {
      if ((e.metaKey || e.ctrlKey) && e.key === 'k') {
        e.preventDefault()
        setOpen(prev => !prev)
        setQuery('')
        setSelectedIdx(0)
      }
      if (e.key === 'Escape' && open) {
        setOpen(false)
      }
    }
    window.addEventListener('keydown', handler)
    return () => window.removeEventListener('keydown', handler)
  }, [open])

  useEffect(() => {
    if (open) setTimeout(() => inputRef.current?.focus(), 50)
  }, [open])

  useEffect(() => { setSelectedIdx(0) }, [query])

  const handleKeyDown = (e: React.KeyboardEvent) => {
    if (e.key === 'ArrowDown') { e.preventDefault(); setSelectedIdx(i => Math.min(i + 1, filtered.length - 1)) }
    if (e.key === 'ArrowUp') { e.preventDefault(); setSelectedIdx(i => Math.max(i - 1, 0)) }
    if (e.key === 'Enter' && filtered[selectedIdx]) { filtered[selectedIdx].action() }
  }

  if (!open) return null

  return (
    <div className="fixed inset-0 z-[100] flex items-start justify-center pt-[20vh]" onClick={() => setOpen(false)}>
      {/* Backdrop */}
      <div className="absolute inset-0 bg-black/60 backdrop-blur-sm" />

      {/* Palette */}
      <div
        className="relative w-full max-w-xl bg-surface border border-border rounded-2xl shadow-2xl overflow-hidden"
        onClick={e => e.stopPropagation()}
      >
        {/* Search */}
        <div className="flex items-center gap-3 px-5 py-4 border-b border-border">
          <Search className="w-5 h-5 text-text-muted shrink-0" />
          <input
            ref={inputRef}
            value={query}
            onChange={e => setQuery(e.target.value)}
            onKeyDown={handleKeyDown}
            placeholder="Search pages, agents, actions..."
            className="flex-1 bg-transparent text-sm text-text outline-none placeholder:text-text-muted"
          />
          <kbd className="text-[10px] text-text-muted bg-surface-2 px-1.5 py-0.5 rounded border border-border font-mono">ESC</kbd>
        </div>

        {/* Results */}
        <div className="max-h-[360px] overflow-y-auto py-2">
          {filtered.length === 0 ? (
            <div className="px-5 py-8 text-center text-text-muted text-sm">
              No results for "{query}"
            </div>
          ) : (
            <>
              {filtered.map((item, i) => {
                const Icon = item.icon
                return (
                  <button
                    key={item.id}
                    onClick={() => item.action()}
                    onMouseEnter={() => setSelectedIdx(i)}
                    className={`w-full flex items-center gap-3 px-5 py-2.5 text-left transition-colors ${
                      i === selectedIdx ? 'bg-accent/10 text-accent' : 'text-text hover:bg-surface-2'
                    }`}
                  >
                    <Icon className="w-4 h-4 shrink-0 opacity-60" />
                    <div className="flex-1 min-w-0">
                      <span className="text-sm font-medium truncate block">{item.label}</span>
                    </div>
                    <span className="text-[10px] text-text-muted bg-surface-2 px-1.5 py-0.5 rounded shrink-0">
                      {item.category}
                    </span>
                  </button>
                )
              })}
            </>
          )}
        </div>

        {/* Footer */}
        <div className="px-5 py-2.5 border-t border-border flex items-center gap-4 text-[10px] text-text-muted">
          <span><kbd className="bg-surface-2 px-1 rounded">↑↓</kbd> navigate</span>
          <span><kbd className="bg-surface-2 px-1 rounded">↵</kbd> select</span>
          <span><kbd className="bg-surface-2 px-1 rounded">esc</kbd> close</span>
        </div>
      </div>
    </div>
  )
}

