import { useState } from 'react'
import { Link, useNavigate } from 'react-router-dom'
import {
  Bot,
  Plus,
  Trash2,
  Clock,
  Globe,
  FolderOpen,
  Search,
  Copy,
  ArrowRightLeft,
  X,
} from 'lucide-react'
import {
  getUnifiedAgents,
  deleteGlobalAgent,
  deleteProjectAgent,
  copyAgent,
  moveAgent,
  updateGlobalAgent,
  updateProjectAgent,
  sanitizeName,
  getCategories,
} from '../lib/api'
import { useApi } from '../hooks/useApi'
import type { UnifiedAgent } from '../types'
import { getProjects } from '../lib/api'
import { toast } from '../components/Toast'
import AgentIcon from '../components/AgentIcon'
import { AgentCategoryBadge, CategoryFilterPills } from '../components/AgentCategoryBadge'

export default function AllAgents() {
  const { data: agents, loading, refetch } = useApi(getUnifiedAgents)
  const { data: projects } = useApi(getProjects)
  const { data: categories } = useApi(getCategories)
  const navigate = useNavigate()

  const [search, setSearch] = useState('')
  const [scopeFilter, setScopeFilter] = useState<'all' | 'global' | 'project'>('all')
  const [categoryFilter, setCategoryFilter] = useState('all')
  const [projectFilter, setProjectFilter] = useState<string>('all')
  const [actionAgent, setActionAgent] = useState<UnifiedAgent | null>(null)
  const [actionType, setActionType] = useState<'copy' | 'move' | null>(null)
  const [actionTarget, setActionTarget] = useState<string>('')
  const [creating, setCreating] = useState(false)
  const [createLoading, setCreateLoading] = useState(false)
  const [newName, setNewName] = useState('')
  const [createScope, setCreateScope] = useState<string>('global')
  const [deletingKeys, setDeletingKeys] = useState<Set<string>>(new Set())
  const [actioning, setActioning] = useState(false)

  const filtered = (agents || []).filter((a) => {
    if (search && !a.name.toLowerCase().includes(search.toLowerCase()) && !a.description.toLowerCase().includes(search.toLowerCase())) return false
    if (scopeFilter === 'global' && a.scope !== 'global') return false
    if (scopeFilter === 'project' && a.scope !== 'project') return false
    if (projectFilter !== 'all' && a.scope === 'project' && a.projectId !== projectFilter) return false
    if (projectFilter !== 'all' && a.scope === 'global' && projectFilter !== 'global') return false
    if (categoryFilter !== 'all' && (a.frontmatter?.category || 'uncategorized') !== categoryFilter) return false
    return true
  })

  // Group by scope
  const globalAgents = filtered.filter((a) => a.scope === 'global')
  const projectGroups = new Map<string, UnifiedAgent[]>()
  for (const a of filtered.filter((a) => a.scope === 'project')) {
    const key = a.projectName || 'Unknown'
    if (!projectGroups.has(key)) projectGroups.set(key, [])
    projectGroups.get(key)!.push(a)
  }

  const handleDelete = async (agent: UnifiedAgent) => {
    if (!confirm(`Delete agent "${agent.name}" from ${agent.scopeLabel}?`)) return
    const key = agent.scope === 'global' ? `global-${agent.filename}` : `${agent.projectId}-${agent.filename}`
    setDeletingKeys((prev) => new Set(prev).add(key))
    try {
      if (agent.scope === 'global') {
        await deleteGlobalAgent(agent.filename)
      } else {
        await deleteProjectAgent(agent.projectId!, agent.filename)
      }
      refetch()
    } catch (err) {
      toast('error', err instanceof Error ? err.message : 'Failed to delete agent')
    } finally {
      setDeletingKeys((prev) => { const s = new Set(prev); s.delete(key); return s })
    }
  }

  const handleAction = async () => {
    if (!actionAgent || !actionType || !actionTarget) return
    setActioning(true)
    try {
      const from = actionAgent.scope === 'global' ? 'global' : actionAgent.projectId!
      const to = actionTarget
      if (actionType === 'copy') {
        await copyAgent(from, to, actionAgent.filename)
        toast('success', `Agent copied`)
      } else {
        await moveAgent(from, to, actionAgent.filename)
        toast('success', `Agent moved`)
      }
      setActionAgent(null)
      setActionType(null)
      setActionTarget('')
      refetch()
    } catch (err) {
      toast('error', err instanceof Error ? err.message : `Failed to ${actionType} agent`)
    } finally {
      setActioning(false)
    }
  }

  const handleCreate = async () => {
    if (!newName.trim()) return
    const slug = sanitizeName(newName)
    if (!slug) {
      toast('error', 'Invalid name — use letters, numbers, or hyphens')
      return
    }
    setCreateLoading(true)
    try {
      const template = `---\nname: ${newName.trim()}\ndescription: ""\nmodel: ""\n---\n\n# ${newName.trim()}\n\nWrite your agent instructions here.\n`
      if (createScope === 'global') {
        await updateGlobalAgent(slug, template)
        navigate(`/global/agents/${slug}`)
      } else {
        await updateProjectAgent(createScope, slug, template)
        navigate(`/projects/${createScope}/agents/${slug}`)
      }
      setCreating(false)
      setNewName('')
    } catch (err) {
      toast('error', err instanceof Error ? err.message : 'Failed to create agent')
    } finally {
      setCreateLoading(false)
    }
  }

  const projectList = projects || []
  const uniqueProjects = [...new Map(projectList.map((p) => [p.id, p])).values()]

  if (loading) return <PageLoader />

  return (
    <div className="p-8 max-w-6xl">
      {/* Header */}
      <div className="flex items-center justify-between mb-6">
        <div>
          <h1 className="text-2xl font-semibold tracking-tight flex items-center gap-3">
            <Bot className="w-6 h-6 text-purple" />
            All Agents
          </h1>
          <p className="text-text-secondary text-sm mt-1">
            {agents?.length || 0} agents across {projectGroups.size} projects + global
          </p>
        </div>
        <button
          onClick={() => setCreating(true)}
          className="flex items-center gap-2 px-4 py-2 text-sm font-medium bg-accent text-white rounded-lg hover:bg-accent-hover transition-colors"
        >
          <Plus className="w-4 h-4" />
          New Agent
        </button>
      </div>

      {/* Category pills */}
      {categories && categories.length > 0 && (
        <div className="mb-4">
          <CategoryFilterPills categories={categories} selected={categoryFilter} onSelect={setCategoryFilter} />
        </div>
      )}

      {/* Filters bar */}
      <div className="flex items-center gap-3 mb-6">
        <div className="relative flex-1 max-w-sm">
          <Search className="w-4 h-4 text-text-muted absolute left-3 top-1/2 -translate-y-1/2" />
          <input
            type="text"
            value={search}
            onChange={(e) => setSearch(e.target.value)}
            placeholder="Search agents..."
            className="w-full bg-surface border border-border rounded-lg pl-9 pr-3 py-2 text-sm focus:outline-none focus:border-accent/50"
          />
        </div>

        <div className="flex items-center gap-1 bg-surface border border-border rounded-lg p-0.5">
          {(['all', 'global', 'project'] as const).map((s) => (
            <button
              key={s}
              onClick={() => setScopeFilter(s)}
              className={`px-3 py-1.5 text-xs font-medium rounded-md transition-colors ${
                scopeFilter === s
                  ? 'bg-accent text-white'
                  : 'text-text-secondary hover:text-text'
              }`}
            >
              {s === 'all' ? 'All' : s === 'global' ? 'Global' : 'Projects'}
            </button>
          ))}
        </div>

        {uniqueProjects.length > 0 && (
          <select
            value={projectFilter}
            onChange={(e) => setProjectFilter(e.target.value)}
            className="bg-surface border border-border rounded-lg px-3 py-2 text-sm text-text-secondary focus:outline-none focus:border-accent/50 appearance-none cursor-pointer"
          >
            <option value="all">All sources</option>
            <option value="global">Global only</option>
            {uniqueProjects.map((p) => (
              <option key={p.id} value={p.id}>
                {p.name}
              </option>
            ))}
          </select>
        )}
      </div>

      {/* Create modal */}
      {creating && (
        <div className="mb-6 bg-surface border border-accent/30 rounded-xl p-5">
          <div className="flex items-center justify-between mb-4">
            <p className="text-sm font-semibold">Create New Agent</p>
            <button onClick={() => { setCreating(false); setNewName('') }} className="text-text-muted hover:text-text">
              <X className="w-4 h-4" />
            </button>
          </div>
          <div className="flex gap-3">
            <input
              type="text"
              value={newName}
              onChange={(e) => setNewName(e.target.value)}
              placeholder="Agent name..."
              className="flex-1 bg-surface-2 border border-border rounded-lg px-3 py-2 text-sm focus:outline-none focus:border-accent/50"
              autoFocus
              onKeyDown={(e) => e.key === 'Enter' && handleCreate()}
            />
            <select
              value={createScope}
              onChange={(e) => setCreateScope(e.target.value)}
              className="bg-surface-2 border border-border rounded-lg px-3 py-2 text-sm text-text-secondary focus:outline-none focus:border-accent/50"
            >
              <option value="global">Global</option>
              {uniqueProjects.map((p) => (
                <option key={p.id} value={p.id}>{p.name}</option>
              ))}
            </select>
            <button
              onClick={handleCreate}
              disabled={createLoading}
              className="px-4 py-2 text-sm font-medium bg-accent text-white rounded-lg hover:bg-accent-hover disabled:opacity-40 disabled:cursor-not-allowed transition-colors"
            >
              {createLoading ? 'Creating...' : 'Create'}
            </button>
          </div>
        </div>
      )}

      {/* Copy/Move modal */}
      {actionAgent && actionType && (
        <div className="mb-6 bg-surface border border-accent/30 rounded-xl p-5">
          <div className="flex items-center justify-between mb-4">
            <p className="text-sm font-semibold">
              {actionType === 'copy' ? 'Copy' : 'Move'} "{actionAgent.name}" from {actionAgent.scopeLabel}
            </p>
            <button onClick={() => { setActionAgent(null); setActionType(null) }} className="text-text-muted hover:text-text">
              <X className="w-4 h-4" />
            </button>
          </div>
          <div className="flex gap-3">
            <select
              value={actionTarget}
              onChange={(e) => setActionTarget(e.target.value)}
              className="flex-1 bg-surface-2 border border-border rounded-lg px-3 py-2 text-sm focus:outline-none focus:border-accent/50"
            >
              <option value="">Select destination...</option>
              {actionAgent.scope !== 'global' && <option value="global">Global</option>}
              {uniqueProjects
                .filter((p) => p.id !== actionAgent.projectId)
                .map((p) => (
                  <option key={p.id} value={p.id}>{p.name}</option>
                ))}
            </select>
            <button
              onClick={handleAction}
              disabled={!actionTarget || actioning}
              className="px-4 py-2 text-sm font-medium bg-accent text-white rounded-lg hover:bg-accent-hover disabled:opacity-40 disabled:cursor-not-allowed transition-colors"
            >
              {actioning ? 'Working...' : actionType === 'copy' ? 'Copy' : 'Move'}
            </button>
          </div>
        </div>
      )}

      {/* Results */}
      {filtered.length === 0 ? (
        <div className="bg-surface rounded-xl border border-border p-12 text-center">
          <Bot className="w-10 h-10 text-text-muted mx-auto mb-3" />
          <p className="text-text-secondary font-medium">
            {search ? 'No agents match your search' : 'No agents found'}
          </p>
          <p className="text-text-muted text-sm mt-1">
            {search ? 'Try a different search term' : 'Create your first agent to get started'}
          </p>
        </div>
      ) : (
        <div className="space-y-8">
          {/* Global agents */}
          {globalAgents.length > 0 && (
            <div>
              <div className="flex items-center gap-2 mb-3">
                <Globe className="w-4 h-4 text-accent" />
                <h2 className="text-sm font-semibold text-text-secondary uppercase tracking-wider">
                  Global
                </h2>
                <span className="text-xs text-text-muted bg-surface-2 px-2 py-0.5 rounded-full">
                  {globalAgents.length}
                </span>
              </div>
              <div className="space-y-2">
                {globalAgents.map((agent) => (
                  <AgentRow
                    key={`global-${agent.filename}`}
                    agent={agent}
                    deleting={deletingKeys.has(`global-${agent.filename}`)}
                    onDelete={handleDelete}
                    onCopy={(a) => { setActionAgent(a); setActionType('copy') }}
                    onMove={(a) => { setActionAgent(a); setActionType('move') }}
                  />
                ))}
              </div>
            </div>
          )}

          {/* Per-project groups */}
          {[...projectGroups.entries()].map(([projectName, projectAgents]) => (
            <div key={projectName}>
              <div className="flex items-center gap-2 mb-3">
                <FolderOpen className="w-4 h-4 text-amber" />
                <h2 className="text-sm font-semibold text-text-secondary uppercase tracking-wider">
                  {projectName}
                </h2>
                <span className="text-xs text-text-muted bg-surface-2 px-2 py-0.5 rounded-full">
                  {projectAgents.length}
                </span>
              </div>
              <div className="space-y-2">
                {projectAgents.map((agent) => (
                  <AgentRow
                    key={`${agent.projectId}-${agent.filename}`}
                    agent={agent}
                    deleting={deletingKeys.has(`${agent.projectId}-${agent.filename}`)}
                    onDelete={handleDelete}
                    onCopy={(a) => { setActionAgent(a); setActionType('copy') }}
                    onMove={(a) => { setActionAgent(a); setActionType('move') }}
                  />
                ))}
              </div>
            </div>
          ))}
        </div>
      )}
    </div>
  )
}


function AgentRow({
  agent,
  deleting,
  onDelete,
  onCopy,
  onMove,
}: {
  agent: UnifiedAgent
  deleting: boolean
  onDelete: (a: UnifiedAgent) => void
  onCopy: (a: UnifiedAgent) => void
  onMove: (a: UnifiedAgent) => void
}) {
  const editLink =
    agent.scope === 'global'
      ? `/global/agents/${agent.filename}`
      : `/projects/${agent.projectId}/agents/${agent.filename}`

  return (
    <div className="group flex items-center justify-between bg-surface border border-border rounded-xl px-4 py-3 hover:border-accent/30 transition-all">
      <Link to={editLink} className="flex items-center gap-3.5 flex-1 min-w-0">
        <AgentIcon name={agent.name} uid={`${agent.scope}-${agent.filename}`} size={agent.scope === 'global' ? 48 : 40} global={agent.scope === 'global'} />
        <div className="min-w-0">
          <div className="flex items-center gap-2">
            <h3 className="font-semibold text-sm group-hover:text-accent-hover transition-colors truncate">
              {agent.name}
            </h3>
            <span
              className={`text-[10px] px-1.5 py-0.5 rounded-md font-medium ${
                agent.scope === 'global'
                  ? 'bg-accent-muted text-accent-hover'
                  : 'bg-amber-muted text-amber'
              }`}
            >
              {agent.scopeLabel}
            </span>
            <AgentCategoryBadge category={agent.frontmatter?.category as string} />
          </div>
          {agent.description && (
            <p className="text-xs text-text-secondary mt-0.5 truncate">{agent.description}</p>
          )}
          <div className="flex items-center gap-3 mt-1.5">
            {agent.model && (
              <span className="text-[11px] text-text-muted bg-surface-2 px-1.5 py-0.5 rounded font-mono">
                {agent.model}
              </span>
            )}
            <span className="flex items-center gap-1 text-[11px] text-text-muted">
              <Clock className="w-3 h-3" />
              {new Date(agent.updatedAt).toLocaleDateString()}
            </span>
          </div>
        </div>
      </Link>

      {/* Actions */}
      <div className="flex items-center gap-1 opacity-0 group-hover:opacity-100 transition-opacity shrink-0 ml-3">
        <button
          onClick={(e) => { e.stopPropagation(); onCopy(agent) }}
          title="Copy to..."
          className="p-1.5 rounded-md text-text-muted hover:text-accent hover:bg-accent-muted transition-colors"
        >
          <Copy className="w-3.5 h-3.5" />
        </button>
        <button
          onClick={(e) => { e.stopPropagation(); onMove(agent) }}
          title="Move to..."
          className="p-1.5 rounded-md text-text-muted hover:text-amber hover:bg-amber-muted transition-colors"
        >
          <ArrowRightLeft className="w-3.5 h-3.5" />
        </button>
        <button
          onClick={(e) => { e.stopPropagation(); onDelete(agent) }}
          title="Delete"
          disabled={deleting}
          className="p-1.5 rounded-md text-text-muted hover:text-red hover:bg-red-muted disabled:opacity-40 disabled:cursor-not-allowed transition-colors"
        >
          <Trash2 className="w-3.5 h-3.5" />
        </button>
      </div>
    </div>
  )
}

function PageLoader() {
  return (
    <div className="p-8 flex items-center justify-center h-64">
      <div className="w-6 h-6 border-2 border-accent border-t-transparent rounded-full animate-spin" />
    </div>
  )
}

import { useState } from 'react'
import { Link, useNavigate } from 'react-router-dom'
import {
  Plus,
  Trash2,
  Clock,
  Globe,
  FolderOpen,
  Search,
  Copy,
  ArrowRightLeft,
  X,
  ChevronDown,
} from 'lucide-react'
import {
  getUnifiedAgents,
  deleteGlobalAgent,
  deleteProjectAgent,
  copyAgent,
  moveAgent,
  updateGlobalAgent,
  updateProjectAgent,
  sanitizeName,
  getCategories,
} from '../lib/api'
import { useApi } from '../hooks/useApi'
import type { UnifiedAgent } from '../types'
import { getProjects } from '../lib/api'
import { toast } from '../components/Toast'
import AgentIcon from '../components/AgentIcon'
import { AgentCategoryBadge, CategoryFilterPills } from '../components/AgentCategoryBadge'

export default function AllAgents() {
  const { data: agents, loading, refetch } = useApi(getUnifiedAgents)
  const { data: projects } = useApi(getProjects)
  const { data: categories } = useApi(getCategories)
  const navigate = useNavigate()

  const [search, setSearch] = useState('')
  const [scopeFilter, setScopeFilter] = useState<'all' | 'global' | 'project'>('all')
  const [categoryFilter, setCategoryFilter] = useState('all')
  const [actionAgent, setActionAgent] = useState<UnifiedAgent | null>(null)
  const [actionType, setActionType] = useState<'copy' | 'move' | null>(null)
  const [actionTarget, setActionTarget] = useState<string>('')
  const [creating, setCreating] = useState(false)
  const [createLoading, setCreateLoading] = useState(false)
  const [newName, setNewName] = useState('')
  const [newCategory, setNewCategory] = useState('software-factory')
  const [createScope, setCreateScope] = useState<string>('global')
  const [deletingKeys, setDeletingKeys] = useState<Set<string>>(new Set())
  const [actioning, setActioning] = useState(false)
  const [viewMode, setViewMode] = useState<'list' | 'grid'>('list')

  const filtered = (agents || []).filter((a) => {
    if (search && !a.name.toLowerCase().includes(search.toLowerCase()) && !a.description.toLowerCase().includes(search.toLowerCase()) && !a.filename.toLowerCase().includes(search.toLowerCase())) return false
    if (scopeFilter === 'global' && a.scope !== 'global') return false
    if (scopeFilter === 'project' && a.scope !== 'project') return false
    if (categoryFilter !== 'all' && (a.frontmatter?.category || 'uncategorized') !== categoryFilter) return false
    return true
  })

  const globalAgents = filtered.filter((a) => a.scope === 'global')
  const projectGroups = new Map<string, UnifiedAgent[]>()
  for (const a of filtered.filter((a) => a.scope === 'project')) {
    const key = a.projectName || 'Unknown'
    if (!projectGroups.has(key)) projectGroups.set(key, [])
    projectGroups.get(key)!.push(a)
  }

  const handleDelete = async (agent: UnifiedAgent) => {
    if (!confirm(`Delete "${agent.name}"?`)) return
    const key = agent.scope === 'global' ? `global-${agent.filename}` : `${agent.projectId}-${agent.filename}`
    setDeletingKeys((prev) => new Set(prev).add(key))
    try {
      if (agent.scope === 'global') await deleteGlobalAgent(agent.filename)
      else await deleteProjectAgent(agent.projectId!, agent.filename)
      refetch()
    } catch (err) {
      toast('error', err instanceof Error ? err.message : 'Failed to delete')
    } finally {
      setDeletingKeys((prev) => { const s = new Set(prev); s.delete(key); return s })
    }
  }

  const handleAction = async () => {
    if (!actionAgent || !actionType || !actionTarget) return
    setActioning(true)
    try {
      const from = actionAgent.scope === 'global' ? 'global' : actionAgent.projectId!
      if (actionType === 'copy') { await copyAgent(from, actionTarget, actionAgent.filename); toast('success', 'Copied') }
      else { await moveAgent(from, actionTarget, actionAgent.filename); toast('success', 'Moved') }
      setActionAgent(null); setActionType(null); setActionTarget(''); refetch()
    } catch (err) {
      toast('error', err instanceof Error ? err.message : 'Failed')
    } finally { setActioning(false) }
  }

  const handleCreate = async () => {
    if (!newName.trim()) return
    const slug = sanitizeName(newName)
    if (!slug) { toast('error', 'Invalid name'); return }
    setCreateLoading(true)
    try {
      const template = `---\nname: ${newName.trim()}\ndescription: ""\nmodel: sonnet\ncategory: ${newCategory}\n---\n\n# ${newName.trim()}\n\nWrite your agent instructions here.\n`
      if (createScope === 'global') { await updateGlobalAgent(slug, template); navigate(`/global/agents/${slug}`) }
      else { await updateProjectAgent(createScope, slug, template); navigate(`/projects/${createScope}/agents/${slug}`) }
      setCreating(false); setNewName('')
    } catch (err) {
      toast('error', err instanceof Error ? err.message : 'Failed')
    } finally { setCreateLoading(false) }
  }

  const uniqueProjects = [...new Map((projects || []).map((p) => [p.id, p])).values()]
  const allCategoryNames = categories ? categories.map(c => c.name) : ['software-factory']

  if (loading) return <div className="p-8 flex items-center justify-center h-64"><div className="w-6 h-6 border-2 border-accent border-t-transparent rounded-full animate-spin" /></div>

  return (
    <div className="p-6 max-w-6xl">
      {/* Compact header */}
      <div className="flex items-center justify-between mb-4">
        <div className="flex items-center gap-3">
          <h1 className="text-xl font-bold tracking-tight">Agents</h1>
          <span className="text-xs text-text-muted bg-surface-2 px-2 py-0.5 rounded-full">{agents?.length || 0}</span>
        </div>
        <button
          onClick={() => setCreating(true)}
          className="flex items-center gap-1.5 px-3 py-1.5 text-xs font-medium bg-accent text-white rounded-lg hover:bg-accent-hover transition-colors"
        >
          <Plus className="w-3.5 h-3.5" /> New Agent
        </button>
      </div>

      {/* Unified filter bar */}
      <div className="bg-surface rounded-xl border border-border p-3 mb-4 space-y-3">
        {/* Row 1: Search + Scope + View */}
        <div className="flex items-center gap-2">
          <div className="relative flex-1">
            <Search className="w-4 h-4 text-text-muted absolute left-3 top-1/2 -translate-y-1/2" />
            <input
              value={search}
              onChange={(e) => setSearch(e.target.value)}
              placeholder="Search by name, description, or filename..."
              className="w-full bg-surface-2 border border-border rounded-lg pl-9 pr-3 py-2 text-sm focus:outline-none focus:border-accent/50"
            />
            {search && (
              <button onClick={() => setSearch('')} className="absolute right-2 top-1/2 -translate-y-1/2 p-0.5 rounded hover:bg-surface text-text-muted">
                <X className="w-3.5 h-3.5" />
              </button>
            )}
          </div>
          <div className="flex bg-surface-2 rounded-lg p-0.5 shrink-0">
            {(['all', 'global', 'project'] as const).map((s) => (
              <button
                key={s}
                onClick={() => setScopeFilter(s)}
                className={`px-2.5 py-1.5 text-[11px] font-medium rounded-md transition-colors ${
                  scopeFilter === s ? 'bg-accent text-white' : 'text-text-muted hover:text-text'
                }`}
              >
                {s === 'all' ? 'All' : s === 'global' ? 'Global' : 'Project'}
              </button>
            ))}
          </div>
          <div className="flex bg-surface-2 rounded-lg p-0.5 shrink-0">
            <button
              onClick={() => setViewMode('list')}
              className={`px-2 py-1.5 text-[11px] font-medium rounded-md transition-colors ${viewMode === 'list' ? 'bg-accent text-white' : 'text-text-muted'}`}
            >
              List
            </button>
            <button
              onClick={() => setViewMode('grid')}
              className={`px-2 py-1.5 text-[11px] font-medium rounded-md transition-colors ${viewMode === 'grid' ? 'bg-accent text-white' : 'text-text-muted'}`}
            >
              Grid
            </button>
          </div>
        </div>

        {/* Row 2: Category pills */}
        {categories && categories.length > 0 && (
          <CategoryFilterPills categories={categories} selected={categoryFilter} onSelect={setCategoryFilter} />
        )}
      </div>

      {/* Create panel */}
      {creating && (
        <div className="bg-surface border border-accent/20 rounded-xl p-4 mb-4">
          <div className="flex items-center justify-between mb-3">
            <span className="text-sm font-semibold">New Agent</span>
            <button onClick={() => { setCreating(false); setNewName('') }} className="text-text-muted hover:text-text"><X className="w-4 h-4" /></button>
          </div>
          <div className="flex gap-2">
            <input
              value={newName}
              onChange={(e) => setNewName(e.target.value)}
              placeholder="Agent name..."
              className="flex-1 bg-surface-2 border border-border rounded-lg px-3 py-2 text-sm focus:outline-none focus:border-accent/50"
              autoFocus
              onKeyDown={(e) => e.key === 'Enter' && handleCreate()}
            />
            <select value={newCategory} onChange={e => setNewCategory(e.target.value)} className="bg-surface-2 border border-border rounded-lg px-2 py-2 text-xs">
              {allCategoryNames.map(c => <option key={c} value={c}>{c.replace(/-/g, ' ')}</option>)}
              <option value="personal">Personal</option>
              <option value="client-work">Client Work</option>
              <option value="automation">Automation</option>
            </select>
            <select value={createScope} onChange={(e) => setCreateScope(e.target.value)} className="bg-surface-2 border border-border rounded-lg px-2 py-2 text-xs">
              <option value="global">Global</option>
              {uniqueProjects.map((p) => <option key={p.id} value={p.id}>{p.name}</option>)}
            </select>
            <button onClick={handleCreate} disabled={createLoading} className="px-4 py-2 text-xs font-medium bg-accent text-white rounded-lg hover:bg-accent-hover disabled:opacity-40">
              {createLoading ? '...' : 'Create'}
            </button>
          </div>
        </div>
      )}

      {/* Copy/Move panel */}
      {actionAgent && actionType && (
        <div className="bg-surface border border-accent/20 rounded-xl p-4 mb-4">
          <div className="flex items-center justify-between mb-3">
            <span className="text-sm font-semibold">{actionType === 'copy' ? 'Copy' : 'Move'} "{actionAgent.name}"</span>
            <button onClick={() => { setActionAgent(null); setActionType(null) }} className="text-text-muted hover:text-text"><X className="w-4 h-4" /></button>
          </div>
          <div className="flex gap-2">
            <select value={actionTarget} onChange={(e) => setActionTarget(e.target.value)} className="flex-1 bg-surface-2 border border-border rounded-lg px-3 py-2 text-sm">
              <option value="">Select destination...</option>
              {actionAgent.scope !== 'global' && <option value="global">Global</option>}
              {uniqueProjects.filter((p) => p.id !== actionAgent.projectId).map((p) => <option key={p.id} value={p.id}>{p.name}</option>)}
            </select>
            <button onClick={handleAction} disabled={!actionTarget || actioning} className="px-4 py-2 text-xs font-medium bg-accent text-white rounded-lg hover:bg-accent-hover disabled:opacity-40">
              {actioning ? '...' : actionType === 'copy' ? 'Copy' : 'Move'}
            </button>
          </div>
        </div>
      )}

      {/* Results */}
      {filtered.length === 0 ? (
        <div className="bg-surface rounded-xl border border-border p-12 text-center text-text-muted">
          <p className="text-sm font-medium">{search ? 'No agents match' : 'No agents found'}</p>
          <p className="text-xs mt-1">{search ? 'Try a different search' : 'Create your first agent'}</p>
        </div>
      ) : viewMode === 'grid' ? (
        /* Grid view */
        <div className="space-y-6">
          {globalAgents.length > 0 && (
            <div>
              <SectionHeader icon={Globe} label="Global" count={globalAgents.length} />
              <div className="grid grid-cols-2 lg:grid-cols-3 gap-3">
                {globalAgents.map(agent => <AgentCard key={`g-${agent.filename}`} agent={agent} onDelete={handleDelete} deleting={deletingKeys.has(`global-${agent.filename}`)} />)}
              </div>
            </div>
          )}
          {[...projectGroups.entries()].map(([name, agents]) => (
            <div key={name}>
              <SectionHeader icon={FolderOpen} label={name} count={agents.length} color="text-amber-400" />
              <div className="grid grid-cols-2 lg:grid-cols-3 gap-3">
                {agents.map(agent => <AgentCard key={`p-${agent.projectId}-${agent.filename}`} agent={agent} onDelete={handleDelete} deleting={deletingKeys.has(`${agent.projectId}-${agent.filename}`)} />)}
              </div>
            </div>
          ))}
        </div>
      ) : (
        /* List view */
        <div className="space-y-6">
          {globalAgents.length > 0 && (
            <div>
              <SectionHeader icon={Globe} label="Global" count={globalAgents.length} />
              <div className="space-y-1">
                {globalAgents.map((agent) => (
                  <AgentRow
                    key={`global-${agent.filename}`}
                    agent={agent}
                    deleting={deletingKeys.has(`global-${agent.filename}`)}
                    onDelete={handleDelete}
                    onCopy={(a) => { setActionAgent(a); setActionType('copy') }}
                    onMove={(a) => { setActionAgent(a); setActionType('move') }}
                  />
                ))}
              </div>
            </div>
          )}
          {[...projectGroups.entries()].map(([projectName, projectAgents]) => (
            <div key={projectName}>
              <SectionHeader icon={FolderOpen} label={projectName} count={projectAgents.length} color="text-amber-400" />
              <div className="space-y-1">
                {projectAgents.map((agent) => (
                  <AgentRow
                    key={`${agent.projectId}-${agent.filename}`}
                    agent={agent}
                    deleting={deletingKeys.has(`${agent.projectId}-${agent.filename}`)}
                    onDelete={handleDelete}
                    onCopy={(a) => { setActionAgent(a); setActionType('copy') }}
                    onMove={(a) => { setActionAgent(a); setActionType('move') }}
                  />
                ))}
              </div>
            </div>
          ))}
        </div>
      )}
    </div>
  )
}

function SectionHeader({ icon: Icon, label, count, color = 'text-accent' }: { icon: React.ElementType; label: string; count: number; color?: string }) {
  return (
    <div className="flex items-center gap-2 mb-2">
      <Icon className={`w-3.5 h-3.5 ${color}`} />
      <span className="text-[11px] font-semibold text-text-muted uppercase tracking-wider">{label}</span>
      <span className="text-[10px] text-text-muted bg-surface-2 px-1.5 py-0.5 rounded-full">{count}</span>
    </div>
  )
}

function AgentCard({ agent, onDelete, deleting }: { agent: UnifiedAgent; onDelete: (a: UnifiedAgent) => void; deleting: boolean }) {
  const editLink = agent.scope === 'global' ? `/global/agents/${agent.filename}` : `/projects/${agent.projectId}/agents/${agent.filename}`
  const emoji = agent.name.match(/^(\p{Emoji_Presentation}|\p{Extended_Pictographic})/u)?.[0] || ''
  const cleanName = agent.name.replace(/^[\p{Emoji_Presentation}\p{Extended_Pictographic}]\s*[\u200d\ufe0f]*/u, '').replace(/^—\s*/, '').trim()

  return (
    <Link to={editLink} className="group bg-surface border border-border rounded-xl p-3.5 hover:border-accent/30 transition-all block">
      <div className="flex items-start justify-between mb-2">
        <div className="flex items-center gap-2">
          {emoji && <span className="text-lg">{emoji}</span>}
          <span className="text-sm font-semibold group-hover:text-accent-hover transition-colors truncate">{cleanName}</span>
        </div>
        <button onClick={e => { e.preventDefault(); e.stopPropagation(); onDelete(agent) }} disabled={deleting} className="p-1 rounded text-text-muted hover:text-red-400 opacity-0 group-hover:opacity-100 transition-opacity">
          <Trash2 className="w-3 h-3" />
        </button>
      </div>
      <p className="text-[11px] text-text-muted line-clamp-2 mb-2">{agent.description}</p>
      <div className="flex items-center gap-2 flex-wrap">
        <span className="text-[10px] font-mono bg-surface-2 px-1.5 py-0.5 rounded text-text-muted">{agent.model || 'sonnet'}</span>
        <AgentCategoryBadge category={agent.frontmatter?.category as string} />
      </div>
    </Link>
  )
}

function AgentRow({
  agent, deleting, onDelete, onCopy, onMove,
}: {
  agent: UnifiedAgent; deleting: boolean; onDelete: (a: UnifiedAgent) => void; onCopy: (a: UnifiedAgent) => void; onMove: (a: UnifiedAgent) => void
}) {
  const editLink = agent.scope === 'global' ? `/global/agents/${agent.filename}` : `/projects/${agent.projectId}/agents/${agent.filename}`

  return (
    <div className="group flex items-center justify-between bg-surface border border-border rounded-lg px-3 py-2.5 hover:border-accent/20 transition-all">
      <Link to={editLink} className="flex items-center gap-3 flex-1 min-w-0">
        <AgentIcon name={agent.name} uid={`${agent.scope}-${agent.filename}`} size={36} global={agent.scope === 'global'} />
        <div className="min-w-0 flex-1">
          <div className="flex items-center gap-2">
            <span className="text-sm font-semibold group-hover:text-accent-hover transition-colors truncate">{agent.name}</span>
            <AgentCategoryBadge category={agent.frontmatter?.category as string} />
          </div>
          <p className="text-[11px] text-text-muted truncate mt-0.5">{agent.description}</p>
        </div>
        <div className="flex items-center gap-2 shrink-0">
          <span className="text-[10px] font-mono bg-surface-2 px-1.5 py-0.5 rounded text-text-muted">{agent.model || 'sonnet'}</span>
          <span className="text-[10px] text-text-muted flex items-center gap-1"><Clock className="w-3 h-3" />{new Date(agent.updatedAt).toLocaleDateString('en-US', { month: 'short', day: 'numeric' })}</span>
        </div>
      </Link>
      <div className="flex items-center gap-0.5 opacity-0 group-hover:opacity-100 transition-opacity shrink-0 ml-2">
        <button onClick={(e) => { e.stopPropagation(); onCopy(agent) }} title="Copy" className="p-1.5 rounded-md text-text-muted hover:text-accent hover:bg-accent-muted"><Copy className="w-3 h-3" /></button>
        <button onClick={(e) => { e.stopPropagation(); onMove(agent) }} title="Move" className="p-1.5 rounded-md text-text-muted hover:text-amber-400 hover:bg-amber-500/10"><ArrowRightLeft className="w-3 h-3" /></button>
        <button onClick={(e) => { e.stopPropagation(); onDelete(agent) }} title="Delete" disabled={deleting} className="p-1.5 rounded-md text-text-muted hover:text-red-400 hover:bg-red-500/10 disabled:opacity-40"><Trash2 className="w-3 h-3" /></button>
      </div>
    </div>
  )
}

