import { useState, useEffect } from 'react'
import { Link } from 'react-router-dom'
import {
  Bot,
  FolderOpen,
  Terminal,
  ShieldCheck,
  Settings,
  Play,
  FileText,
} from 'lucide-react'
import type { Project } from '../types'
import { getUnifiedAgents, getCategories, getTemplates } from '../lib/api'
import { useApi } from '../hooks/useApi'
import { AgentCategoryBadge } from '../components/AgentCategoryBadge'
import AgentIcon from '../components/AgentIcon'

interface Props {
  projects: Project[]
}

export default function Dashboard({ projects }: Props) {
  const { data: allAgents } = useApi(getUnifiedAgents)
  const { data: categories } = useApi(getCategories)
  const { data: templates } = useApi(getTemplates)
  const [serviceStatus, setServiceStatus] = useState<'ok' | 'warn' | null>(null)

  useEffect(() => {
    fetch('/api/setup/status')
      .then(r => r.json())
      .then((d: { pm2Status: string; agentCount: number }) => {
        setServiceStatus(d.pm2Status === 'online' && d.agentCount > 0 ? 'ok' : 'warn')
      })
      .catch(() => setServiceStatus('warn'))
  }, [])

  const totalAgents = allAgents?.length || 0
  const globalAgents = allAgents?.filter((a) => a.scope === 'global').length || 0
  const totalCommands = projects.reduce((sum, p) => sum + p.commands.length, 0)
  const totalRules = projects.reduce((sum, p) => sum + p.rules.length, 0)

  const stats = [
    { label: 'Projects', value: projects.length, icon: FolderOpen, color: 'text-accent', bg: 'bg-accent-muted', link: '/settings' },
