import { NavLink, useLocation, useNavigate } from 'react-router-dom'
import { useState, useEffect, useCallback, useRef } from 'react'
import {
  LayoutDashboard,
  FileText,
  Bot,
  FolderOpen,
  Settings,
  ChevronRight,
  ChevronDown,
  Zap,
  Terminal,
  ShieldCheck,
  Sparkles,
  FlaskConical,
  Wrench,
  BookOpen,
  Network,
  Sun,
  Moon,
  Brain,
  Maximize,
  Minimize,
  LayoutTemplate,
  BarChart3,
  Activity,
  Clock,
  Globe,
  Users,
  Target,
  Search,
  Check,
  MessageSquare,
} from 'lucide-react'
import type { Project } from '../types'
import { useTheme } from '../contexts/ThemeContext'

interface SidebarProps {
  projects: Project[]
}

const navLinkClass = ({ isActive }: { isActive: boolean }) =>
  `flex items-center gap-3 px-4 py-1.5 text-[13px] rounded-lg mx-2 transition-all ${
    isActive
      ? 'bg-accent-muted text-accent-hover font-medium'
      : 'text-text-secondary hover:text-text hover:bg-surface-2'
  }`

function CollapsibleSection({ title, children, defaultOpen = true, count }: {
  title: string
  children: React.ReactNode
  defaultOpen?: boolean
  count?: number
}) {
  const [open, setOpen] = useState(defaultOpen)
  return (
    <div>
      <button
        onClick={() => setOpen(!open)}
        className="w-full flex items-center justify-between px-5 mb-1 group cursor-pointer"
      >
        <p className="text-[10px] font-semibold uppercase tracking-wider text-text-muted group-hover:text-text-secondary transition-colors">
          {title}
        </p>
        <div className="flex items-center gap-1.5">
          {count !== undefined && (
            <span className="text-[9px] text-text-muted bg-surface-2 px-1.5 py-0.5 rounded-full">{count}</span>
          )}
          {open
            ? <ChevronDown className="w-3 h-3 text-text-muted" />
            : <ChevronRight className="w-3 h-3 text-text-muted" />
          }
        </div>
      </button>
      {open && children}
    </div>
  )
}

function ProjectSelector({ projects }: { projects: Project[] }) {
  const [open, setOpen] = useState(false)
  const location = useLocation()
  const navigate = useNavigate()
  const ref = useRef<HTMLDivElement>(null)

  // Find active project
  const activeProject = projects.find(p => location.pathname.includes(`/projects/${p.id}`))

  useEffect(() => {
    const handler = (e: MouseEvent) => {
      if (ref.current && !ref.current.contains(e.target as Node)) setOpen(false)
    }
    document.addEventListener('mousedown', handler)
    return () => document.removeEventListener('mousedown', handler)
  }, [])

  if (projects.length === 0) return null

  return (
    <div ref={ref} className="mx-3 mb-2 relative">
      <button
        onClick={() => setOpen(!open)}
        className={`w-full flex items-center gap-2.5 px-3 py-2 text-[13px] rounded-xl border transition-all ${
          activeProject
            ? 'bg-accent/8 border-accent/20 text-accent-hover'
            : 'bg-surface-2/50 border-border text-text-secondary hover:bg-surface-2 hover:text-text'
        }`}
      >
        <FolderOpen className="w-4 h-4 shrink-0" />
        <span className="flex-1 text-left truncate font-medium">
          {activeProject ? activeProject.name : 'Select project...'}
        </span>
        <div className="flex items-center gap-1 shrink-0">
          <span className="text-[9px] bg-surface-2 text-text-muted px-1.5 py-0.5 rounded-full">{projects.length}</span>
          <ChevronDown className={`w-3.5 h-3.5 text-text-muted transition-transform ${open ? 'rotate-180' : ''}`} />
        </div>
      </button>

      {/* Dropdown */}
      {open && (
        <div className="absolute left-0 right-0 top-full mt-1 bg-surface border border-border rounded-xl shadow-xl z-50 overflow-hidden">
          <div className="py-1 max-h-[280px] overflow-y-auto">
            {projects.map((p) => {
              const isActive = activeProject?.id === p.id
              return (
                <button
                  key={p.id}
                  onClick={() => { navigate(`/projects/${p.id}`); setOpen(false) }}
                  className={`w-full flex items-center gap-3 px-3 py-2 text-[13px] transition-colors ${
                    isActive
                      ? 'bg-accent/10 text-accent-hover'
                      : 'text-text-secondary hover:bg-surface-2 hover:text-text'
                  }`}
                >
                  <FolderOpen className="w-3.5 h-3.5 shrink-0" />
                  <span className="flex-1 text-left truncate">{p.name}</span>
                  <div className="flex items-center gap-2 shrink-0">
                    {p.agentCount > 0 && (
                      <span className="text-[9px] text-text-muted bg-surface-2 px-1.5 py-0.5 rounded-full">
                        {p.agentCount} agents
                      </span>
                    )}
                    {isActive && <Check className="w-3.5 h-3.5 text-accent" />}
                  </div>
                </button>
              )
            })}
          </div>
        </div>
      )}
    </div>
  )
}

export default function Sidebar({ projects }: SidebarProps) {
  const location = useLocation()
  const { theme, toggle } = useTheme()
  const [isFullscreen, setIsFullscreen] = useState(false)

  useEffect(() => {
    const handler = () => setIsFullscreen(!!document.fullscreenElement)
