import { useState, useEffect, useMemo, useCallback } from 'react'
import {
  ReactFlow,
  Background,
  Controls,
  MiniMap,
  useNodesState,
  useEdgesState,
  type Node,
  type Edge,
  type NodeTypes,
  Handle,
  Position,
  BackgroundVariant,
  ReactFlowProvider,
} from '@xyflow/react'
import '@xyflow/react/dist/style.css'
import {
  Users, Search, Cpu, Paintbrush, BarChart3, Shield,
  X, ChevronDown, ChevronRight, GitBranch, LayoutGrid, List,
} from 'lucide-react'
import { getOrgChart } from '../lib/api'
import type { OrgChartData, OrgChartNode } from '../lib/api'
import AgentIcon from '../components/AgentIcon'

// ── Constants ────────────────────────────────────────────────────────────────

const NODE_WIDTH = 240
const H_GAP = 40
const LEVEL_HEIGHT = 180
const ROOT_GAP = 160

const TIER_ICONS: Record<string, typeof Cpu> = {
  leadership: Shield,
  engineer: Cpu,
  analyst: BarChart3,
  creative: Paintbrush,
}

const MODEL_BADGES: Record<string, { label: string; bg: string; text: string; border: string }> = {
  opus: { label: 'Opus', bg: 'rgba(168,85,247,0.15)', text: '#c084fc', border: 'rgba(168,85,247,0.3)' },
  sonnet: { label: 'Sonnet', bg: 'rgba(96,165,250,0.15)', text: '#60a5fa', border: 'rgba(96,165,250,0.3)' },
}

function extractEmoji(name: string): { emoji: string; cleanName: string } {
  const emoji = name.match(/^(\p{Emoji_Presentation}|\p{Extended_Pictographic})/u)?.[0] || ''
  const cleanName = name
    .replace(/^[\p{Emoji_Presentation}\p{Extended_Pictographic}]\s*[\u200d\ufe0f]*/u, '')
    .replace(/^—\s*/, '')
    .trim()
  return { emoji, cleanName: cleanName.split('—')[0]?.trim() || cleanName }
}

// ── Tree Layout Algorithm ────────────────────────────────────────────────────

interface LayoutResult {
  width: number
  nodes: Array<{ id: string; x: number; y: number }>
  edges: Array<{ source: string; target: string }>
}

function layoutSubtree(
  nodeId: string,
  childrenMap: Map<string, OrgChartNode[]>,
  depth: number,
): LayoutResult {
  const children = childrenMap.get(nodeId) || []

  if (children.length === 0) {
    return {
      width: NODE_WIDTH,
      nodes: [{ id: nodeId, x: 0, y: depth * LEVEL_HEIGHT }],
      edges: [],
    }
  }

  const childLayouts = children.map(c => layoutSubtree(c.id, childrenMap, depth + 1))
  const totalChildWidth = childLayouts.reduce((sum, l) => sum + l.width, 0)
    + (children.length - 1) * H_GAP

  let currentX = 0
  const allChildNodes: LayoutResult['nodes'] = []
  const allChildEdges: LayoutResult['edges'] = []

  for (let i = 0; i < childLayouts.length; i++) {
    const layout = childLayouts[i]
    for (const node of layout.nodes) {
      allChildNodes.push({ ...node, x: node.x + currentX })
    }
    allChildEdges.push(...layout.edges)
    allChildEdges.push({ source: nodeId, target: children[i].id })
    currentX += layout.width + H_GAP
  }

  const subtreeWidth = Math.max(totalChildWidth, NODE_WIDTH)
  const parentX = totalChildWidth / 2 - NODE_WIDTH / 2

  return {
    width: subtreeWidth,
    nodes: [{ id: nodeId, x: parentX, y: depth * LEVEL_HEIGHT }, ...allChildNodes],
    edges: allChildEdges,
  }
}

// ── Node data interface ──────────────────────────────────────────────────────

interface OrgAgentNodeData {
  agentId: string
  name: string
  emoji: string
  title: string
  model: string
  tier: string
  phaseColor: string
  phaseLabel: string | null
  description: string
  tools: string
  reportsTo: string | null
  childCount: number
  dimmed: boolean
  [key: string]: unknown
}

function computeTreeLayout(allNodes: OrgChartNode[]): {
  rfNodes: Node<OrgAgentNodeData>[]
  rfEdges: Edge[]
} {
  // Pre-compute children map for O(1) lookups (avoids O(n) filter per node)
  const childrenMap = new Map<string, OrgChartNode[]>()
  const nodeMap = new Map<string, OrgChartNode>()
  for (const n of allNodes) {
    nodeMap.set(n.id, n)
    const parentKey = n.reportsTo ?? '__root__'
    const siblings = childrenMap.get(parentKey)
    if (siblings) siblings.push(n)
    else childrenMap.set(parentKey, [n])
  }

  const roots = childrenMap.get('__root__') || []
  const subtrees = roots.map(r => layoutSubtree(r.id, childrenMap, 0))

  // Place root subtrees side by side
  let offsetX = 0
  const finalNodes: Array<{ id: string; x: number; y: number }> = []
  const finalEdges: Array<{ source: string; target: string }> = []

  for (const subtree of subtrees) {
    for (const node of subtree.nodes) {
      finalNodes.push({ ...node, x: node.x + offsetX })
    }
    finalEdges.push(...subtree.edges)
    offsetX += subtree.width + ROOT_GAP
  }

  const rfNodes: Node<OrgAgentNodeData>[] = finalNodes
    .reduce<Node<OrgAgentNodeData>[]>((acc, pos) => {
      const node = nodeMap.get(pos.id)
      if (!node) return acc
      const { emoji, cleanName } = extractEmoji(node.name)
      const childCount = (childrenMap.get(node.id) || []).length

      acc.push({
        id: pos.id,
        type: 'orgAgent',
        position: { x: pos.x, y: pos.y },
        data: {
          agentId: node.id,
          name: cleanName,
          emoji,
          title: node.title,
          model: node.model,
          tier: node.tier,
          phaseColor: node.phaseColor,
          phaseLabel: node.phaseLabel,
          description: node.description,
          tools: node.tools,
          reportsTo: node.reportsTo,
          childCount,
          dimmed: false,
        },
      })
      return acc
    }, [])

  const rfEdges: Edge[] = finalEdges.map(e => ({
    id: `e-${e.source}-${e.target}`,
    source: e.source,
    target: e.target,
    type: 'smoothstep',
    style: {
      stroke: nodeMap.get(e.target)?.phaseColor || 'var(--color-border)',
      strokeWidth: 2,
      opacity: 0.6,
    },
  }))

  return { rfNodes, rfEdges }
}

// ── Custom ReactFlow Node ────────────────────────────────────────────────────
// Matches Orchestration.tsx pattern: plain function, no memo, no NodeProps generic

function OrgChartAgentNode({ data, selected }: { data: OrgAgentNodeData; selected: boolean }) {
  const badge = MODEL_BADGES[data.model]
  const TierIcon = TIER_ICONS[data.tier] || Cpu

  return (
    <div
      className="transition-opacity duration-200"
      style={{ opacity: data.dimmed ? 0.15 : 1 }}
    >
      <Handle
        type="target"
        position={Position.Top}
        className="!w-2 !h-2 !bg-transparent !border-0 !top-0"
      />

      <div
        className={`relative rounded-xl border-2 bg-surface backdrop-blur-sm transition-all duration-200 cursor-pointer
          ${selected
            ? 'shadow-lg ring-2 ring-accent/40 ring-offset-2 ring-offset-bg'
            : 'shadow-md hover:shadow-lg hover:border-accent/30'
          }`}
        style={{
          width: NODE_WIDTH,
          borderColor: selected ? 'var(--color-accent)' : 'var(--color-border)',
          borderLeftWidth: 4,
          borderLeftColor: data.phaseColor,
        }}
      >
        <div className="px-3.5 py-3.5">
          {/* Top row: icon + name + model badge */}
          <div className="flex items-center gap-2.5 mb-1.5">
            <AgentIcon
              name={data.name}
              uid={`org-${data.agentId}`}
              size={32}
              global
            />
            <div className="min-w-0 flex-1">
              <div className="flex items-center gap-1.5">
                <span className="text-[13px] font-bold truncate leading-tight">{data.name}</span>
                {badge && (
                  <span
                    className="text-[9px] px-1.5 py-0.5 rounded-full font-semibold shrink-0"
                    style={{
                      backgroundColor: badge.bg,
                      color: badge.text,
                      border: `1px solid ${badge.border}`,
                    }}
                  >
                    {badge.label}
                  </span>
                )}
              </div>
            </div>
          </div>

          {/* Bottom row: tier icon + title + phase */}
          <div className="flex items-center gap-1.5 ml-[42px]">
            <TierIcon className="w-3 h-3 text-text-muted shrink-0" />
            <span className="text-[11px] text-text-muted truncate">{data.title}</span>
            {data.phaseLabel && (
              <>
                <span className="text-text-muted/30 shrink-0">&middot;</span>
