// Topological sort helper
function topoSort(nodes, edges) {
  const inDegree = {};
  const adj = {};
  for (const n of nodes) { inDegree[n.id] = 0; adj[n.id] = []; }
  for (const e of edges) {
    adj[e.source].push(e.target);
    inDegree[e.target] = (inDegree[e.target] || 0) + 1;
  }
  const queue = nodes.filter(n => inDegree[n.id] === 0).map(n => n.id);
  const order = [];
  while (queue.length) {
    const id = queue.shift();
    order.push(id);
    for (const next of adj[id]) {
      inDegree[next]--;
      if (inDegree[next] === 0) queue.push(next);
    }
  }
  return order;
}

// Level-based grouping for parallel execution
function topoLevels(nodes, edges) {
  const inDegree = {};
  const adj = {};
  for (const n of nodes) { inDegree[n.id] = 0; adj[n.id] = []; }
  for (const e of edges) {
    adj[e.source] = adj[e.source] || [];
    adj[e.source].push(e.target);
    inDegree[e.target] = (inDegree[e.target] || 0) + 1;
  }
  const levels = [];
  let queue = nodes.filter(n => inDegree[n.id] === 0).map(n => n.id);
  while (queue.length) {
    levels.push([...queue]);
    const nextQueue = [];
    for (const id of queue) {
      for (const next of (adj[id] || [])) {
        inDegree[next]--;
        if (inDegree[next] === 0) nextQueue.push(next);
      }
    }
    queue = nextQueue;
  }
  return levels;
}

function sleep(ms) { return new Promise(resolve => setTimeout(resolve, ms)); }

// Failure alerting — send to Slack if configured
async function sendFailureAlert(agentName, nodeLabel, error, orchestrationName) {
  try {
    const settings = loadGlobalSettings();
    const url = settings.slackWebhookUrl;
    if (!url || !settings.alertOnFailure) return;
    const payload = {
      text: `:warning: *Agent Failure* in Claude Hub`,
      blocks: [
        { type: 'header', text: { type: 'plain_text', text: 'Agent Failure Alert' } },
        { type: 'section', fields: [
          { type: 'mrkdwn', text: `*Agent:*\n${agentName}` },
          { type: 'mrkdwn', text: `*Node:*\n${nodeLabel}` },
          { type: 'mrkdwn', text: `*Pipeline:*\n${orchestrationName || 'Direct'}` },
          { type: 'mrkdwn', text: `*Error:*\n${(error || '').slice(0, 200)}` },
        ]},
      ],
    };
    const http = require('http');
    const https = require('https');
    const parsed = new URL(url);
    const lib = parsed.protocol === 'https:' ? https : http;
    const req = lib.request({ hostname: parsed.hostname, port: parsed.port, path: parsed.pathname, method: 'POST', headers: { 'Content-Type': 'application/json' } });
    req.write(JSON.stringify(payload));
    req.end();
  } catch {}
}

// ── Pending Approvals — human-in-the-loop gates ─────────────────────────────
const APPROVALS_PATH = path.join(__dirname, '..', 'pending-approvals.json');
const pendingApprovalResolvers = new Map(); // runId:nodeId → { resolve, reject, timer }

function loadApprovals() {
  try { if (fs.existsSync(APPROVALS_PATH)) return JSON.parse(fs.readFileSync(APPROVALS_PATH, 'utf-8')); } catch {} return [];
}
function saveApprovals(list) {
  fs.writeFileSync(APPROVALS_PATH, JSON.stringify(list, null, 2));
}

function waitForApproval(runId, nodeId, nodeLabel, timeoutMinutes = 60) {
  return new Promise((resolve, reject) => {
    const key = `${runId}:${nodeId}`;
    const timer = setTimeout(() => {
      pendingApprovalResolvers.delete(key);
      // Remove from pending file
      saveApprovals(loadApprovals().filter(a => a.key !== key));
      reject(new Error(`Approval timed out after ${timeoutMinutes} minutes`));
    }, timeoutMinutes * 60 * 1000);

    pendingApprovalResolvers.set(key, { resolve, reject, timer });

    // Persist to file
    const approvals = loadApprovals();
    approvals.push({ key, runId, nodeId, nodeLabel, createdAt: new Date().toISOString(), timeoutMinutes });
    saveApprovals(approvals);
  });
}

function runClaudeSync(prompt, timeoutMs = 120000) {
  return new Promise((resolve, reject) => {
    const claudePath = process.env.CLAUDE_PATH || 'claude';
    const childEnv = { ...process.env, HOME: os.homedir() };
    delete childEnv.CLAUDECODE;
    const proc = spawn(claudePath, ['-p'], { env: childEnv });
    let out = '', err = '';
    let killed = false;

    const timer = setTimeout(() => {
      killed = true;
      proc.kill('SIGTERM');
      setTimeout(() => { try { proc.kill('SIGKILL'); } catch {} }, 5000);
    }, timeoutMs);

    proc.stdout.on('data', d => { out += d.toString(); });
    proc.stderr.on('data', d => { err += d.toString(); });
    proc.on('close', code => {
      clearTimeout(timer);
      if (killed) reject(new Error(`Node execution timed out after ${timeoutMs / 1000}s`));
      else if (code !== 0) reject(new Error(err.trim() || `claude exited ${code}`));
      else resolve(out.trim());
    });
    proc.on('error', (e) => { clearTimeout(timer); reject(e); });
    proc.stdin.write(prompt, 'utf8');
    proc.stdin.end();
  });
}

app.post('/api/orchestrations/run', rateLimit('heavy'), async (req, res) => {
  res.setTimeout(0);
  const { nodes, edges, task } = req.body;
  if (!Array.isArray(nodes) || !task) return res.status(400).json({ error: 'nodes and task required' });

  const nodeMap = Object.fromEntries(nodes.map(n => [n.id, n]));
  const order = topoSort(nodes, edges || []);

  // Build agent content map from files
  const config = loadConfig();
  const projects = discoverProjects(config.projectDirs);
  const agentContentMap = {};

  const globalAgents = listAgents(path.join(CLAUDE_DIR, 'agents'));
  for (const a of globalAgents) agentContentMap[a.name] = a.body || a.raw;

  for (const p of projects) {
    for (const a of p.agents) agentContentMap[a.name] = a.body || a.raw;
  }

  const results = {};
  let lastOutput = task;
  const runId = genId();
  const startedAt = new Date().toISOString();
  const runLogs = [];
  let runStatus = 'completed';

  // SSE for streaming progress
  res.setHeader('Content-Type', 'text/event-stream');
  res.setHeader('Cache-Control', 'no-cache');
  res.setHeader('Connection', 'keep-alive');

  const send = (data) => {
    runLogs.push(data);
    res.write(`data: ${JSON.stringify(data)}\n\n`);
  };

  // Execute a single node (with retry + backoff + condition + approval)
  async function executeNode(nodeId) {
    const node = nodeMap[nodeId];
    if (!node) return;

    // Start/task-input nodes
    if (node.data?.isStart) {
      results[nodeId] = task;
      send({ type: 'done', nodeId, label: node.data?.label || nodeId, output: task, skipped: true });
      return;
    }

    // Approval gate nodes
    if (node.data?.isApproval) {
      const nodeLabel = node.data?.label || 'Approval';
      send({ type: 'waiting_approval', nodeId, label: nodeLabel });
      try {
        await waitForApproval(runId, nodeId, nodeLabel, node.data?.timeoutMinutes || 60);
        results[nodeId] = '[APPROVED]';
        send({ type: 'done', nodeId, label: nodeLabel, output: '[APPROVED]' });
      } catch (err) {
        runStatus = 'failed';
        results[nodeId] = `[REJECTED: ${err.message}]`;
        send({ type: 'error', nodeId, label: nodeLabel, error: err.message });
        throw err;
      }
      return;
    }

    const agentName = node.data?.agentName;
    const baseInstructions = agentName ? (agentContentMap[agentName] || '') : '';
    const nodeInstructions = node.data?.instructions || '';
    const nodeLabel = node.data?.label || agentName || nodeId;

    send({ type: 'start', nodeId, label: nodeLabel });

    // Build context from upstream outputs
    const incomingEdges = (edges || []).filter(e => e.target === nodeId);
    let context = '';
    if (incomingEdges.length > 0) {
      context = incomingEdges.map(e => {
        const prevLabel = nodeMap[e.source]?.data?.label || e.source;
        return `## Output from ${prevLabel}:\n${results[e.source] || ''}`;
      }).join('\n\n');
    } else {
      context = `## Task:\n${task}`;
    }

    let prompt = '';
    if (baseInstructions) prompt += baseInstructions + '\n\n';
    if (nodeInstructions) prompt += `## Your Specific Task for This Step:\n${nodeInstructions}\n\n`;
    prompt += `---\n\n${context}\n\n`;
    prompt += `---\n\nIMPORTANT: Produce the actual deliverable directly. Do NOT write meta-commentary, evaluations, or descriptions of what you would do. Output only the finished work product itself.`;

    // Condition check
    const condition = node.data?.condition;
    if (condition) {
      const incomingOutputs = incomingEdges.map(e => results[e.source] || '').join('\n');
      if (!incomingOutputs.includes(condition)) {
        results[nodeId] = `[SKIPPED: condition "${condition}" not matched]`;
        send({ type: 'skipped', nodeId, label: nodeLabel, condition });
        return;
      }
    }

    // Retry with exponential backoff
    const maxRetries = Math.min(node.data?.retryCount || 0, 3);
    let attempt = 0;
    let nodeOutput = null;
    let lastErr = null;

    while (attempt <= maxRetries) {
      const nodeStart = Date.now();
      try {
        if (attempt > 0) {
          const backoffMs = Math.pow(2, attempt) * 1000; // 2s, 4s, 8s
          send({ type: 'retry', nodeId, label: nodeLabel, attempt, backoffMs });
          await sleep(backoffMs);
        }
        nodeOutput = await runClaudeSync(prompt);
        logAgentRun({ agentName: agentName || 'custom', prompt: prompt.slice(0, 500), output: nodeOutput, source: 'orchestration', duration: Date.now() - nodeStart, status: 'success', metadata: { orchestrationId: req.body.orchestrationId, nodeId, attempt } });
        break;
      } catch (err) {
        lastErr = err;
        logAgentRun({ agentName: agentName || 'custom', prompt: prompt.slice(0, 500), output: '', source: 'orchestration', duration: Date.now() - nodeStart, status: 'error', error: err.message, metadata: { orchestrationId: req.body.orchestrationId, nodeId, attempt } });
        attempt++;
      }
    }

    if (nodeOutput !== null) {
      results[nodeId] = nodeOutput;
      lastOutput = nodeOutput;
      send({ type: 'done', nodeId, label: nodeLabel, output: nodeOutput });
    } else {
      // Try fallback agent if specified
      const fallbackAgent = node.data?.fallbackAgent;
      if (fallbackAgent && agentContentMap[fallbackAgent]) {
        send({ type: 'fallback', nodeId, label: nodeLabel, fallbackAgent });
        const fbPrompt = (agentContentMap[fallbackAgent] || '') + '\n\n' + prompt.split('---')[1];
        try {
          nodeOutput = await runClaudeSync(fbPrompt);
          results[nodeId] = nodeOutput;
          lastOutput = nodeOutput;
          send({ type: 'done', nodeId, label: nodeLabel, output: nodeOutput, usedFallback: true });
          return;
        } catch {}
      }

      runStatus = 'failed';
      send({ type: 'error', nodeId, label: nodeLabel, error: lastErr?.message || 'Unknown error', retries: maxRetries });
      sendFailureAlert(agentName || 'custom', nodeLabel, lastErr?.message, req.body.orchestrationName);
      throw lastErr || new Error('Node failed');
    }
  }

  // PARALLEL EXECUTION — group by level, run same-level nodes concurrently
  try {
    const levels = topoLevels(nodes, edges || []);
    for (const level of levels) {
      if (level.length === 1) {
        await executeNode(level[0]);
      } else {
        // Parallel: run all nodes at this level concurrently
        send({ type: 'parallel_start', nodeIds: level, count: level.length });
        await Promise.all(level.map(nodeId => executeNode(nodeId)));
        send({ type: 'parallel_done', nodeIds: level });
      }
    }
    send({ type: 'complete', finalOutput: lastOutput });
  } catch (err) {
    runStatus = 'failed';
    if (!err._handled) send({ type: 'error', nodeId: null, label: null, error: err.message });
  }

  // Persist run session to history
  const completedAt = new Date().toISOString();
  const duration = new Date(completedAt) - new Date(startedAt);
  const runSession = {
    id: runId,
    orchestrationName: req.body.orchestrationName || 'Untitled',
    orchestrationId: req.body.orchestrationId || null,
    task,
    status: runStatus,
    nodeCount: nodes.length,
    nodes: nodes.map(n => ({ id: n.id, label: n.data?.label, agentName: n.data?.agentName, isStart: n.data?.isStart, isCustom: n.data?.isCustom })),
    edges: (edges || []).map(e => ({ source: e.source, target: e.target })),
    logs: runLogs,
    nodeOutputs: results,
    finalOutput: lastOutput,
    startedAt,
    completedAt,
    duration,
  };
  try {
    const history = loadRunHistory();
    history.unshift(runSession);
    saveRunHistory(history);
  } catch {}

  res.end();
});

// Agent Playground — test any agent with a prompt (SSE streaming)
app.post('/api/playground/run', rateLimit('heavy'), (req, res) => {
  const { agentName, prompt: userPrompt, customInstructions, timeoutMs } = req.body;
  if (!userPrompt) return res.status(400).json({ error: 'Prompt is required' });

  res.setTimeout(0);
  res.setHeader('Content-Type', 'text/event-stream');
  res.setHeader('Cache-Control', 'no-cache');
  res.setHeader('Connection', 'keep-alive');

  const send = (data) => res.write(`data: ${JSON.stringify(data)}\n\n`);

  // Load agent instructions
  let instructions = '';
  if (agentName) {
    const agentContentMap = {};
    const globalAgentsDir = path.join(CLAUDE_DIR, 'agents');
    if (fs.existsSync(globalAgentsDir)) {
      for (const file of fs.readdirSync(globalAgentsDir).filter(f => f.endsWith('.md'))) {
        const content = fs.readFileSync(path.join(globalAgentsDir, file), 'utf-8');
        const nameMatch = content.match(/^name:\s*(.+)$/m);
        const key = nameMatch ? nameMatch[1].trim() : file.replace('.md', '');
        agentContentMap[key] = content;
        agentContentMap[file.replace('.md', '')] = content;
      }
    }
    // Also check project agents
    const config = loadConfig();
    const projects = discoverProjects(config.projectDirs);
    for (const p of projects) {
      for (const a of (p.agents || [])) {
        agentContentMap[a.name] = a.body || a.raw;
        agentContentMap[a.filename] = a.body || a.raw;
      }
    }
    instructions = agentContentMap[agentName] || '';

    // Agent not found — warn the user
    if (!instructions) {
      send({ type: 'error', error: `Agent "${agentName}" not found in global or project agents` });
      res.end();
      return;
    }

    // Inject output template if agent has one
    try {
      const agentPath = path.join(CLAUDE_DIR, 'agents', agentName + '.md');
      if (fs.existsSync(agentPath)) {
        const { data: agentMeta } = matter(fs.readFileSync(agentPath, 'utf-8'));
        if (agentMeta.output_template) {
          const tmplPath = path.join(TEMPLATES_DIR, agentMeta.output_template + '.md');
          if (fs.existsSync(tmplPath)) {
            const { content: tmplBody } = matter(fs.readFileSync(tmplPath, 'utf-8'));
            instructions += '\n\n## OUTPUT FORMAT (MANDATORY)\nYou MUST structure your response exactly as follows. Do not deviate from this format.\n\n' + tmplBody.trim();
          }
        }
      }
    } catch {}

    // Inject training corrections if any
    try {
      const agentKey = agentName.replace(/\s.*$/, '').toLowerCase();
      const trainingFiles = [agentName, agentKey].map(n => path.join(TRAINING_DIR, n + '.json'));
      for (const tf of trainingFiles) {
        if (fs.existsSync(tf)) {
          const corrections = JSON.parse(fs.readFileSync(tf, 'utf-8')).filter(c => c.status === 'active');
          if (corrections.length > 0) {
            instructions += '\n\n## TRAINING CORRECTIONS (Follow these strictly)\n' +
              corrections.map((c, i) => `${i + 1}. [${c.timestamp.split('T')[0]}] ${c.correction}`).join('\n');
          }
          break;
        }
      }
    } catch {}
  }

  if (customInstructions) {
    instructions = customInstructions;
  }

  let fullPrompt = '';
  if (instructions) {
    fullPrompt = `${instructions}\n\n---\n\n## Task:\n${userPrompt}\n\n---\n\nIMPORTANT: Produce the actual deliverable directly. Do NOT write meta-commentary. Output only the finished work product.`;
  } else {
    fullPrompt = userPrompt;
  }

  const timeout = Math.min(timeoutMs ?? 120000, 600000); // max 10 min, ?? avoids 0 becoming falsy
  const claudePath = process.env.CLAUDE_PATH || 'claude';
  const childEnv = { ...process.env, HOME: os.homedir() };
  delete childEnv.CLAUDECODE;
  const proc = spawn(claudePath, ['-p'], { env: childEnv });
  let fullOutput = '';
  let killed = false;
  let ended = false; // Guard against double res.end()

  const finish = () => {
    if (ended) return;
    ended = true;
    try { res.end(); } catch {}
  };

  const timer = setTimeout(() => {
    killed = true;
    proc.kill('SIGTERM');
    setTimeout(() => { try { proc.kill('SIGKILL'); } catch {} }, 5000);
  }, timeout);

  const playgroundStartTime = Date.now();
  send({ type: 'start', agent: agentName || 'custom' });

  proc.stdout.on('data', (data) => {
    if (ended) return;
    const chunk = data.toString();
    fullOutput += chunk;
    try { send({ type: 'chunk', content: chunk }); } catch {}
  });

  proc.stderr.on('data', (data) => {
    if (ended) return;
    const msg = data.toString().trim();
    if (msg) {
      try { send({ type: 'activity', message: msg }); } catch {}
    }
  });

  proc.on('close', (code) => {
    clearTimeout(timer);
    if (ended) return;
    const runSource = req.body.source || 'playground';
    if (killed) {
      send({ type: 'error', error: `Timed out after ${timeout / 1000}s` });
      logAgentRun({ agentName: agentName || 'custom', prompt: userPrompt, output: '', source: runSource, duration: Date.now() - playgroundStartTime, status: 'error', error: `Timed out after ${timeout / 1000}s` });
    } else if (code !== 0 && !fullOutput.trim()) {
      send({ type: 'error', error: `Process exited with code ${code}` });
      logAgentRun({ agentName: agentName || 'custom', prompt: userPrompt, output: '', source: runSource, duration: Date.now() - playgroundStartTime, status: 'error', error: `Process exited with code ${code}` });
    } else {
      send({ type: 'done', output: fullOutput.trim() });
      logAgentRun({ agentName: agentName || 'custom', prompt: userPrompt, output: fullOutput.trim(), source: runSource, duration: Date.now() - playgroundStartTime, status: 'success' });
    }
    finish();
  });

  proc.on('error', (err) => {
    clearTimeout(timer);
    if (ended) return;
    send({ type: 'error', error: err.message });
    finish();
  });

  proc.stdin.write(fullPrompt, 'utf8');
  proc.stdin.end();

  // Handle client disconnect — kill the process
  req.on('close', () => {
    clearTimeout(timer);
    ended = true;
    if (!proc.killed) {
      proc.kill('SIGTERM');
      setTimeout(() => { try { proc.kill('SIGKILL'); } catch {} }, 3000);
    }
  });
});

