  res.json(versions.map(f => {
    const stat = fs.statSync(path.join(agentDir, f));
    return { filename: f, timestamp: f.replace('.md', '').replace(/-/g, (m, i) => i > 15 ? '.' : i === 10 ? 'T' : '-') + 'Z', size: stat.size };
  }));
});

