// ── Search helper (shared between tree and list views) ───────────────────────

function computeSearchSets(allNodes: OrgChartNode[], search: string) {
  if (!search) return { matchIds: null, relevantIds: null }

  const q = search.toLowerCase()
  const matchIds = new Set(
    allNodes
      .filter(n =>
        n.name.toLowerCase().includes(q)
        || n.title.toLowerCase().includes(q)
        || n.id.toLowerCase().includes(q)
        || (n.description || '').toLowerCase().includes(q),
      )
      .map(n => n.id),
  )

  // Include ancestors of matches so tree paths stay visible
  const relevantIds = new Set<string>()
  const addAncestors = (id: string) => {
    if (relevantIds.has(id)) return // prevent cycles
    relevantIds.add(id)
    const node = allNodes.find(n => n.id === id)
    if (node?.reportsTo) addAncestors(node.reportsTo)
  }
  matchIds.forEach(id => addAncestors(id))

  return { matchIds, relevantIds }
}

// ── Tree View (ReactFlow) ────────────────────────────────────────────────────

function TreeViewInner({
  data,
  search,
  selectedNode,
  onSelectNode,
}: {
  data: OrgChartData
  search: string
  selectedNode: string | null
  onSelectNode: (id: string | null) => void
}) {
  const { rfNodes: initialNodes, rfEdges: initialEdges } = useMemo(
    () => computeTreeLayout(data.nodes),
    [data.nodes],
  )

  const [nodes, setNodes, onNodesChange] = useNodesState(initialNodes)
  const [edges, setEdges, onEdgesChange] = useEdgesState(initialEdges)

  // Apply search dimming (no fitView -- let user pan/zoom manually)
  useEffect(() => {
    const { relevantIds } = computeSearchSets(data.nodes, search)

    setNodes(nds =>
      nds.map(n => ({
        ...n,
        data: { ...n.data, dimmed: relevantIds ? !relevantIds.has(n.id) : false },
      })),
    )
    setEdges(eds =>
      eds.map(e => ({
        ...e,
        style: {
          ...e.style,
          opacity: !relevantIds || (relevantIds.has(e.source) && relevantIds.has(e.target))
            ? 0.6
            : 0.08,
        },
      })),
    )
  }, [search, data.nodes, setNodes, setEdges])

  const handleNodeClick = useCallback(
    (_: React.MouseEvent, node: Node) => {
      onSelectNode(node.id === selectedNode ? null : node.id)
    },
    [onSelectNode, selectedNode],
  )

  const handlePaneClick = useCallback(() => {
    onSelectNode(null)
  }, [onSelectNode])

  return (
    <ReactFlow
      nodes={nodes}
      edges={edges}
      onNodesChange={onNodesChange}
      onEdgesChange={onEdgesChange}
      onNodeClick={handleNodeClick}
      onPaneClick={handlePaneClick}
      nodeTypes={nodeTypes}
      nodesDraggable={false}
      nodesConnectable={false}
      elementsSelectable
      fitView
      fitViewOptions={{ padding: 0.15, maxZoom: 0.85 }}
      minZoom={0.15}
      maxZoom={1.5}
      proOptions={{ hideAttribution: true }}
      className="bg-bg"
    >
      <Background variant={BackgroundVariant.Dots} gap={20} size={1} className="!bg-bg" />
      <Controls
        showInteractive={false}
        className="!bg-surface !border-border !rounded-xl !shadow-lg [&>button]:!bg-surface [&>button]:!border-border [&>button]:!text-text-muted [&>button:hover]:!bg-surface-2"
      />
      <MiniMap
        nodeColor={(n) => {
          const d = n.data as Record<string, unknown>
          return (typeof d.phaseColor === 'string' ? d.phaseColor : null) || '#6b7280'
        }}
        maskColor="rgba(0,0,0,0.2)"
        className="!bg-surface !border-border !rounded-xl"
        pannable
        zoomable
      />
    </ReactFlow>
  )
}

function TreeView(props: {
  data: OrgChartData
  search: string
  selectedNode: string | null
  onSelectNode: (id: string | null) => void
}) {
  return (
    <ReactFlowProvider>
      <TreeViewInner {...props} />
    </ReactFlowProvider>
  )
}

// ── Pipeline View ────────────────────────────────────────────────────────────

function PipelineView({ data, search }: { data: OrgChartData; search: string }) {
  return (
    <div className="space-y-6">
      {/* Pipeline flow indicator */}
      <div className="flex items-center gap-2 overflow-x-auto pb-2">
        {data.phases.map((phase, i) => (
          <div key={phase.id} className="flex items-center gap-2 shrink-0">
            <div
              className="px-3.5 py-1.5 rounded-full text-xs font-bold text-white shadow-sm"
              style={{ backgroundColor: phase.color }}
            >
              {phase.label}
            </div>
            {i < data.phases.length - 1 && (
              <div className="w-8 h-[2px] bg-border" />
            )}
          </div>
        ))}
      </div>

      {/* Phase cards */}
      {data.phases.map(phase => {
        const q = search.toLowerCase()
        const agents = search
          ? phase.agents.filter(a =>
              a.name.toLowerCase().includes(q)
              || a.title.toLowerCase().includes(q)
              || a.id.toLowerCase().includes(q),
            )
          : phase.agents
        if (search && agents.length === 0) return null
        return (
          <div key={phase.id} className="bg-surface rounded-2xl border border-border overflow-hidden">
            <div
              className="px-5 py-3 border-b border-border flex items-center gap-3"
              style={{ borderLeftWidth: 4, borderLeftColor: phase.color }}
            >
              <div>
                <h2 className="text-sm font-bold" style={{ color: phase.color }}>{phase.label}</h2>
                <p className="text-[11px] text-text-muted">{phase.description}</p>
              </div>
              <span className="ml-auto text-[10px] bg-surface-2 text-text-muted px-2 py-0.5 rounded-full">
                {agents.length} agents
              </span>
            </div>
            <div className="p-4 grid grid-cols-1 md:grid-cols-2 lg:grid-cols-3 gap-3">
              {agents.map(agent => {
                const { cleanName } = extractEmoji(agent.name)
                const badge = MODEL_BADGES[agent.model]
                return (
                  <div
                    key={agent.id}
                    className="bg-surface-2/50 rounded-xl p-3.5 border border-border/50 hover:border-border hover:shadow-md transition-all"
                  >
                    <div className="flex items-center gap-2.5 mb-2">
                      <AgentIcon name={cleanName} uid={`pipe-${agent.id}`} size={28} global />
                      <span className="text-sm font-semibold truncate">{cleanName}</span>
                      {badge && (
                        <span
                          className="text-[9px] px-1.5 py-0.5 rounded-full font-semibold ml-auto shrink-0"
                          style={{ backgroundColor: badge.bg, color: badge.text, border: `1px solid ${badge.border}` }}
                        >
                          {badge.label}
                        </span>
                      )}
                    </div>
                    <p className="text-[11px] text-text-muted font-medium mb-1">{agent.title}</p>
                    <p className="text-[10px] text-text-muted leading-relaxed line-clamp-2">{agent.description}</p>
                  </div>
                )
              })}
            </div>
          </div>
        )
      })}
    </div>
  )
}

// ── List View (Hierarchy) ────────────────────────────────────────────────────

function ListAgentCard({ node, depth }: { node: OrgChartNode; depth: number }) {
  const [showDetail, setShowDetail] = useState(false)
  const { emoji, cleanName } = extractEmoji(node.name)
  const badge = MODEL_BADGES[node.model]
  const TierIcon = TIER_ICONS[node.tier] || Cpu

  return (
    <div style={{ marginLeft: depth > 0 ? 24 : 0 }}>
      <div
        className={`group relative bg-surface rounded-xl border transition-all hover:border-accent/30 cursor-pointer ${
          showDetail ? 'border-accent/40 shadow-lg shadow-accent/5' : 'border-border'
        }`}
        onClick={() => setShowDetail(!showDetail)}
      >
        {depth > 0 && (
          <div
            className="absolute -left-[13px] top-[22px] w-[13px] h-[2px]"
            style={{ backgroundColor: node.phaseColor || '#6b7280' }}
          />
        )}

        <div className="p-3 flex items-center gap-3">
          <div
            className="w-2.5 h-2.5 rounded-full shrink-0 ring-2 ring-offset-1 ring-offset-surface"
            style={{ backgroundColor: node.phaseColor, boxShadow: `0 0 8px ${node.phaseColor}40` }}
          />
          <div className="flex-1 min-w-0">
            <div className="flex items-center gap-2">
              {emoji && <span className="text-base">{emoji}</span>}
              <span className="text-sm font-semibold truncate">{cleanName}</span>
              {badge && (
                <span
                  className="text-[9px] px-1.5 py-0.5 rounded-full font-medium"
                  style={{ backgroundColor: badge.bg, color: badge.text, border: `1px solid ${badge.border}` }}
                >
                  {badge.label}
                </span>
              )}
            </div>
            <div className="flex items-center gap-2 mt-0.5">
              <TierIcon className="w-3 h-3 text-text-muted" />
              <span className="text-[11px] text-text-muted">{node.title}</span>
              {node.phaseLabel && (
                <>
                  <span className="text-text-muted/30">|</span>
                  <span className="text-[10px] font-medium" style={{ color: node.phaseColor }}>{node.phaseLabel}</span>
                </>
              )}
            </div>
          </div>
        </div>

        {showDetail && (
          <div className="px-3 pb-3 pt-0 border-t border-border/50">
            <div className="pt-3 space-y-2">
              <p className="text-xs text-text-muted leading-relaxed">{node.description}</p>
              {node.tools && (
                <div className="flex flex-wrap gap-1">
                  {node.tools.split(',').map(t => (
                    <span key={t.trim()} className="text-[9px] px-1.5 py-0.5 rounded bg-surface-2 text-text-muted font-mono">
                      {t.trim()}
                    </span>
                  ))}
                </div>
              )}
              {node.reportsTo && (
                <p className="text-[10px] text-text-muted">
                  Reports to: <span className="text-text font-medium">{node.reportsTo}</span>
                </p>
              )}
            </div>
          </div>
        )}
      </div>
    </div>
  )
}

function ListView({
  data,
  search,
  expanded,
  onToggleExpand,
}: {
  data: OrgChartData
  search: string
  expanded: Set<string>
  onToggleExpand: (id: string) => void
}) {
  // Pre-compute search sets once (not per recursive call)
  const { matchIds, relevantIds } = useMemo(
    () => computeSearchSets(data.nodes, search),
    [data.nodes, search],
  )

  const childrenMap = useMemo(() => {
    const map = new Map<string | null, OrgChartNode[]>()
    for (const n of data.nodes) {
      const key = n.reportsTo
      const siblings = map.get(key)
      if (siblings) siblings.push(n)
      else map.set(key, [n])
    }
    return map
  }, [data.nodes])

  const renderTree = (parentId: string | null, depth: number): React.ReactNode[] => {
    const children = (childrenMap.get(parentId) || [])
      .filter(n => !relevantIds || relevantIds.has(n.id))

    return children.map(node => {
      const nodeChildren = (childrenMap.get(node.id) || [])
        .filter(n => !relevantIds || relevantIds.has(n.id))
      const isOpen = expanded.has(node.id) || (matchIds !== null && matchIds.has(node.id))

      return (
        <div key={node.id} className="relative">
          {depth > 0 && (
            <div
              className="absolute left-[11px] top-0 bottom-0 w-[2px]"
              style={{ backgroundColor: `${node.phaseColor}20` }}
            />
          )}
          <div className="flex items-center gap-1">
            {nodeChildren.length > 0 ? (
              <button
                onClick={() => onToggleExpand(node.id)}
                className="p-0.5 rounded hover:bg-surface-2 text-text-muted shrink-0"
              >
                {isOpen
                  ? <ChevronDown className="w-3.5 h-3.5" />
                  : <ChevronRight className="w-3.5 h-3.5" />}
              </button>
            ) : (
              <div className="w-[18px]" />
            )}
            <div className="flex-1">
              <ListAgentCard node={node} depth={depth} />
            </div>
          </div>
          {isOpen && nodeChildren.length > 0 && (
            <div className="mt-1.5 space-y-1.5">
              {renderTree(node.id, depth + 1)}
            </div>
          )}
        </div>
      )
    })
  }

  return <div className="space-y-2">{renderTree(null, 0)}</div>
}

// ── Main Page ────────────────────────────────────────────────────────────────

const VIEW_OPTIONS = [
  { id: 'tree' as const, label: 'Tree', icon: GitBranch },
  { id: 'pipeline' as const, label: 'Pipeline', icon: LayoutGrid },
  { id: 'list' as const, label: 'List', icon: List },
]

type ViewType = 'tree' | 'pipeline' | 'list'

export default function OrgChartPage() {
  const [data, setData] = useState<OrgChartData | null>(null)
  const [loading, setLoading] = useState(true)
  const [error, setError] = useState<string | null>(null)
  const [view, setView] = useState<ViewType>('tree')
  const [expanded, setExpanded] = useState<Set<string>>(new Set(['rex', 'arya']))
  const [search, setSearch] = useState('')
  const [selectedNode, setSelectedNode] = useState<string | null>(null)

  useEffect(() => {
    getOrgChart()
      .then(setData)
      .catch((e: unknown) => {
        setError(e instanceof Error ? e.message : 'Failed to load org chart')
      })
      .finally(() => setLoading(false))
  }, [])

  const toggleExpand = useCallback((id: string) => {
    setExpanded(prev => {
      const next = new Set(prev)
      if (next.has(id)) next.delete(id)
      else next.add(id)
      return next
    })
  }, [])

  const selectedNodeData = useMemo(
    () => data?.nodes.find(n => n.id === selectedNode) ?? null,
    [data, selectedNode],
  )

  const handleNavigateToNode = useCallback((id: string) => {
    setSelectedNode(id)
  }, [])

  if (loading) {
    return (
      <div className="flex items-center justify-center h-64 text-text-muted">
        <div className="animate-spin w-5 h-5 border-2 border-accent border-t-transparent rounded-full mr-3" />
        Loading org chart...
      </div>
    )
  }

  if (error || !data) {
    return (
      <div className="flex items-center justify-center h-64">
        <div className="text-center">
          <p className="text-red-400 font-medium">{error || 'Failed to load org chart'}</p>
          <button
            onClick={() => {
              setLoading(true)
              setError(null)
              getOrgChart()
                .then(setData)
                .catch((e: unknown) => setError(e instanceof Error ? e.message : 'Failed'))
                .finally(() => setLoading(false))
            }}
            className="mt-3 px-4 py-1.5 text-sm bg-surface-2 rounded-lg hover:bg-surface-3 transition-colors"
          >
            Retry
          </button>
        </div>
      </div>
    )
  }

  return (
    <div className="h-full flex flex-col">
      {/* Header */}
      <div className="px-8 pt-6 pb-4 space-y-4 shrink-0">
        <div className="flex items-center justify-between">
          <div>
            <h1 className="text-2xl font-bold flex items-center gap-2.5">
              <Users className="w-6 h-6" /> Org Chart
            </h1>
            <p className="text-text-muted text-sm mt-1">
              {data.stats.totalAgents} agents &middot; {data.stats.byModel.opus || 0} Opus &middot; {data.stats.byModel.sonnet || 0} Sonnet
            </p>
          </div>

          {/* View toggle */}
          <div className="flex bg-surface-2 rounded-lg p-0.5">
            {VIEW_OPTIONS.map(opt => {
              const Icon = opt.icon
              return (
                <button
                  key={opt.id}
                  onClick={() => setView(opt.id)}
                  className={`flex items-center gap-1.5 px-3 py-1.5 text-xs font-medium rounded-md transition-colors ${
                    view === opt.id
                      ? 'bg-accent text-white'
                      : 'text-text-muted hover:text-text'
                  }`}
                >
                  <Icon className="w-3.5 h-3.5" />
                  {opt.label}
                </button>
              )
            })}
          </div>
        </div>

        {/* Search */}
        <div className="flex items-center gap-3">
          <div className="relative flex-1 max-w-md">
            <Search className="absolute left-3 top-1/2 -translate-y-1/2 w-4 h-4 text-text-muted" />
            <input
              value={search}
              onChange={e => setSearch(e.target.value)}
              placeholder="Search agents..."
              className="w-full pl-9 pr-3 py-2 text-sm bg-surface border border-border rounded-lg focus:border-accent outline-none"
            />
          </div>
          {view === 'list' && (
            <div className="flex gap-1">
              <button
                onClick={() => setExpanded(new Set(data.nodes.map(n => n.id)))}
                className="px-2.5 py-1.5 text-[11px] rounded-lg bg-surface-2 text-text-muted hover:text-text transition-colors"
              >
                Expand All
              </button>
              <button
                onClick={() => setExpanded(new Set())}
                className="px-2.5 py-1.5 text-[11px] rounded-lg bg-surface-2 text-text-muted hover:text-text transition-colors"
              >
                Collapse All
              </button>
            </div>
          )}
        </div>
      </div>

      {/* Content */}
      <div className="flex-1 relative overflow-hidden">
        {view === 'tree' && (
          <div className="h-full mx-8 mb-4 rounded-2xl border border-border overflow-hidden relative">
            <TreeView
              data={data}
              search={search}
              selectedNode={selectedNode}
              onSelectNode={setSelectedNode}
            />
            {selectedNodeData && (
              <DetailPanel
                node={selectedNodeData}
                allNodes={data.nodes}
                onClose={() => setSelectedNode(null)}
                onNavigate={handleNavigateToNode}
              />
            )}
          </div>
        )}

        {view === 'pipeline' && (
          <div className="px-8 pb-8 overflow-y-auto h-full">
            <PipelineView data={data} search={search} />
          </div>
        )}

        {view === 'list' && (
          <div className="px-8 pb-8 overflow-y-auto h-full">
            <ListView
              data={data}
              search={search}
              expanded={expanded}
              onToggleExpand={toggleExpand}
            />
          </div>
        )}
      </div>

      {/* Stats footer */}
      {view !== 'tree' && (
        <div className="px-8 pb-6 shrink-0">
          <div className="grid grid-cols-2 md:grid-cols-4 gap-3">
            {Object.entries(data.stats.byTier)
              .sort(([, a], [, b]) => (b as number) - (a as number))
              .map(([tier, count]) => {
                const TIcon = TIER_ICONS[tier] || Cpu
                return (
                  <div key={tier} className="bg-surface rounded-xl border border-border p-3 flex items-center gap-3">
                    <TIcon className="w-4 h-4 text-text-muted" />
                    <div>
                      <div className="text-xs font-semibold capitalize">{tier}</div>
                      <div className="text-[10px] text-text-muted">{count as number} agents</div>
                    </div>
                  </div>
                )
              })}
          </div>
        </div>
      )}
    </div>
  )
}

